      '@typescript-eslint/no-misused-promises': 'error',
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-empty-object-type': 'off',
      '@typescript-eslint/require-await': 'warn'
    }
  },

  prettier
)

export default {
  '*.{ts,tsx,js,mjs,cjs}': ['eslint --fix', 'prettier --write'],
  '*.{json,md,yml,yaml}': ['prettier --write']
}

import { spawnSync } from 'node:child_process'
import { readFile, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'

const rootDirectory = process.cwd()
const outputFileName = 'project_whole_code_source.json'
const outputFilePath = path.resolve(rootDirectory, outputFileName)
const excludedFiles = ['package-lock.json', 'README.md']

function getRepositoryFiles() {
  const result = spawnSync(
    'git',
    ['ls-files', '-z', '--cached', '--others', '--exclude-standard'],
    {
      cwd: rootDirectory,
      encoding: 'utf8',
      maxBuffer: 100 * 1024 * 1024
    }
  )

  if (result.error) {
    throw new Error(`Не удалось запустить Git: ${result.error.message}`)
  }

  if (result.status !== 0) {
    throw new Error(
      result.stderr.trim() || `Git завершился с кодом ${result.status}`
    )
  }

  return result.stdout
    .split('\0')
    .filter(Boolean)
    .filter((relativePath) => {
      if (excludedFiles.includes(relativePath)) {
        return false
      }
      const absolutePath = path.resolve(rootDirectory, relativePath)

      // Не добавляем предыдущий сгенерированный файл в новый результат.
      return absolutePath !== outputFilePath
    })
    .sort((left, right) => left.localeCompare(right))
}

async function generateProjectSource() {
  const files = getRepositoryFiles()
  const projectSource = []

  for (const relativePath of files) {
    const absolutePath = path.resolve(rootDirectory, relativePath)
    const fileStat = await stat(absolutePath).catch(() => null)

    if (!fileStat?.isFile()) {
      continue
    }

    const codeSource = await readFile(absolutePath, 'utf8')

    projectSource.push({
      path: relativePath.replaceAll(path.sep, '/'),
      code_source: codeSource
    })
  }

  await writeFile(
    outputFilePath,
    `${JSON.stringify(projectSource, null, 2)}\n`,
    'utf8'
  )

  console.log(`Файл создан: ${outputFileName}`)
  console.log(`Добавлено файлов: ${projectSource.length}`)
}

generateProjectSource().catch((error) => {
  console.error(error instanceof Error ? error.message : error)
  process.exitCode = 1
})

import type { Cli } from '~/core/cli'
import type { AppConfig } from '~/core/config'
import type { AgentContextManager } from '~/core/context'
import type { ImplementerAgent } from '~/core/implementation'
import type { InvestigatorAgent } from '~/core/investigation'
import type { Logger } from '~/core/logging'
import type { ModelProvider } from '~/core/model'
import type { ProcessRunnerFactory } from '~/core/process'
import type { PromptRegistry } from '~/core/prompt'
import type { ReproducerAgent } from '~/core/reproduction'
import type { ReviewerAgent } from '~/core/review'
import type { TraceRecorder } from '~/core/trace'
import type { ValidationService } from '~/core/validation'
import type {
  RepositoryToolsFactory,
  WorkspaceManager
} from '~/core/workspace'

export interface ApplicationDependencies {
  readonly config: AppConfig
  readonly modelProvider: ModelProvider
  readonly processRunnerFactory: ProcessRunnerFactory
  readonly promptRegistry: PromptRegistry
  readonly investigatorAgent: InvestigatorAgent
  readonly logger: Logger
  readonly traceRecorder: TraceRecorder
  readonly cli: Cli
  readonly contextManager: AgentContextManager
  readonly workspaceManager: WorkspaceManager
  readonly repositoryToolsFactory: RepositoryToolsFactory
  readonly reproducerAgent: ReproducerAgent
  readonly implementerAgent: ImplementerAgent
  readonly reviewerAgent: ReviewerAgent
  readonly validationService: ValidationService
}

export interface Application {
  start(): Promise<void>
  execute(argv: readonly string[]): Promise<number>
  stop(): Promise<void>
}

type ApplicationStatus = 'created' | 'started' | 'stopped'

export function createApp(
  dependencies: ApplicationDependencies
): Application {
  let status: ApplicationStatus = 'created'

  return {
    async start(): Promise<void> {
      if (status === 'started') {
        return
      }

      if (status === 'stopped') {
        throw new Error('Application cannot be started after shutdown')
      }

      status = 'started'
    },

    execute(argv: readonly string[]): Promise<number> {
      if (status !== 'started') {
        throw new Error(
          'Application must be started before command execution'
        )
      }

      return dependencies.cli.execute(argv)
    },

    async stop(): Promise<void> {
      if (status === 'stopped') {
        return
      }

      status = 'stopped'
    }
  }
}

import type { ReproductionResult } from '~/core/reproduction'
import type {
  RepositoryToolsFactory,
  WorkspaceManager,
  WorkspaceSnapshot
} from '~/core/workspace'

import {
  ExecutionError,
  ExecutionErrorCode,
  ExecutionFailureKind
} from '~/core/execution'

export class ImplementationRetryRecovery {
  constructor(
    private readonly workspaceManager: WorkspaceManager,
    private readonly repositoryToolsFactory: RepositoryToolsFactory
  ) {}

  async restoreReproductionWorkspace(
    workspace: WorkspaceSnapshot,
    reproduction: ReproductionResult
  ): Promise<WorkspaceSnapshot> {
    let rolledBackWorkspace: WorkspaceSnapshot

    try {
      rolledBackWorkspace = await this.workspaceManager.rollback(workspace)
    } catch (error) {
      throw new ExecutionError(
        'Failed to rollback implementation attempt',
        ExecutionErrorCode.rollback_failed,
        {
          kind: ExecutionFailureKind.fatal,
          cause: error
        }
      )
    }

    const repositoryTools = this.repositoryToolsFactory.create(
      rolledBackWorkspace
    )

    try {
      const result = await repositoryTools.applyPatch(reproduction.patch)

      if (result.workspaceRevision !== reproduction.workspaceRevision) {
        throw new ExecutionError(
          'Reapplied reproduction patch produced another workspace revision',
          ExecutionErrorCode.stale_checkpoint,
          {
            kind: ExecutionFailureKind.fatal
          }
        )
      }

      return {
        ...rolledBackWorkspace,
        workspaceRevision: result.workspaceRevision
      }
    } catch (error) {
      if (error instanceof ExecutionError) {
        throw error
      }

      throw new ExecutionError(
        'Failed to restore reproduction patch after rollback',
        ExecutionErrorCode.rollback_failed,
        {
          kind: ExecutionFailureKind.fatal,
          cause: error
        }
      )
    }
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any */
import { describe, expect, it } from 'vitest'
import { RetryExecutor } from '~/application/execution'
import {
  AttemptsExhaustedError,
  ExecutionError,
  ExecutionErrorCode
} from '~/core/execution'

describe('RetryExecutor', () => {
  it('retries retryable failures', async () => {
    const executor = new RetryExecutor(3)

    let attempts = 0

    const result = await executor.execute({
      operation: () => {
        attempts += 1

        if (attempts < 3) {
          throw new ExecutionError(
            'Invalid structured output',
            ExecutionErrorCode.retry_failed,
            {
              retryable: true
            }
          )
        }

        return Promise.resolve('accepted')
      }
    })

    expect(result).toBe('accepted')
    expect(attempts).toBe(3)
  })

  it('does not retry non-retryable failures', async () => {
    const executor = new RetryExecutor(3)

    let attempts = 0

    await expect(
      executor.execute({
        operation: () => {
          attempts += 1

          throw new ExecutionError(
            'Unsafe patch',
            ExecutionErrorCode.retry_failed
          )
        }
      })
    ).rejects.toMatchObject({
      code: ExecutionErrorCode.retry_failed
    })

    expect(attempts).toBe(1)
  })

  it('enforces the maximum attempt limit', async () => {
    const executor = new RetryExecutor(2)

    await expect(
      executor.execute({
        operation: () => {
          throw new ExecutionError(
            'Invalid structured output',
            ExecutionErrorCode.retry_failed,
            {
              retryable: true
            }
          )
        }
      })
    ).rejects.toBeInstanceOf(AttemptsExhaustedError)
  })

  it('passes validation feedback to the next attempt', async () => {
    const executor = new RetryExecutor(2)

    const feedback: readonly string[][] = []

    await executor.execute({
      operation: (context) => {
        const f = feedback as any as string[]
        f.push(context.validationFeedback as any as string)

        if (context.attempt === 1) {
          throw new ExecutionError(
            'Invalid output',
            ExecutionErrorCode.retry_failed,
            {
              retryable: true
            }
          )
        }

        return Promise.resolve('accepted')
      },

      onRetry: () => Promise.resolve(['workspaceRevision is stale'])
    })

    expect(feedback).toEqual([[], ['workspaceRevision is stale']])
  })
})

import type {
  RetryAttemptContext,
  RetryExecutionInput
} from '~/core/execution'

import {
  AttemptsExhaustedError,
  ExecutionError,
  ExecutionErrorCode,
  ExecutionFailureKind,
  isRetryableError
} from '~/core/execution'

export class RetryExecutor {
  constructor(private readonly maximumAttempts: number) {
    if (!Number.isInteger(maximumAttempts) || maximumAttempts <= 0) {
      throw new ExecutionError(
        'Maximum attempt limit must be a positive integer',
        ExecutionErrorCode.invalid_attempt_limit,
        {
          kind: ExecutionFailureKind.fatal
        }
      )
    }
  }

  async execute<T>(input: RetryExecutionInput<T>): Promise<T> {
    let validationFeedback: readonly string[] = []

    let lastError: unknown

    for (let attempt = 1; attempt <= this.maximumAttempts; attempt += 1) {
      const context: RetryAttemptContext = {
        attempt,
        maximumAttempts: this.maximumAttempts,
        validationFeedback
      }

      try {
        return await input.operation(context)
      } catch (error) {
        lastError = error

        if (!isRetryableError(error)) {
          throw error
        }

        if (attempt >= this.maximumAttempts) {
          break
        }

        const feedback = await input.onRetry?.(error, context)

        if (feedback !== undefined) {
          validationFeedback = [...validationFeedback, ...feedback]
        }
      }
    }

    throw new AttemptsExhaustedError(this.maximumAttempts, lastError)
  }
}

import type {
  SaveStepCheckpointInput,
  StepCheckpoint,
  StepCheckpointStore
} from '~/core/execution'

import { describe, expect, it } from 'vitest'
import {
  StepExecutor,
  createExecutionId,
  hashValue
} from '~/application/execution'

class MemoryCheckpointStore implements StepCheckpointStore {
  readonly checkpoints = new Map<string, StepCheckpoint<unknown>>()

  load<T>(
    runId: string,
    executionId: string
  ): Promise<StepCheckpoint<T> | null> {
    const checkpoint = this.checkpoints.get(`${runId}:${executionId}`)

    return Promise.resolve(
      (checkpoint as StepCheckpoint<T> | undefined) ?? null
    )
  }

  save<T>(input: SaveStepCheckpointInput<T>): Promise<StepCheckpoint<T>> {
    const checkpoint: StepCheckpoint<T> = {
      schemaVersion: 1,
      runId: input.runId,
      step: input.step,
      executionId: input.executionId,
      inputHash: input.inputHash,
      outputHash: input.outputHash,
      attempt: input.attempt,
      workspaceRevision: input.workspaceRevision,
      createdAt: '2026-08-05T09:00:00.000Z',
      output: input.output
    }

    this.checkpoints.set(`${input.runId}:${input.executionId}`, checkpoint)

    return Promise.resolve(checkpoint)
  }
}

describe('StepExecutor', () => {
  it('assigns a deterministic execution identifier', async () => {
    const store = new MemoryCheckpointStore()

    const executor = new StepExecutor(store)

    const input = {
      runId: 'run-001',
      step: 'investigator',
      attempt: 1,
      input: {
        task: 'Fix duplicate payment'
      },
      execute: () =>
        Promise.resolve({
          hypothesis: 'Duplicate insert'
        })
    }

    const first = await executor.execute(input)

    const second = await executor.execute(input)

    expect(first.executionId).toBe(second.executionId)
  })

  it('saves input and output hashes', async () => {
    const store = new MemoryCheckpointStore()

    const executor = new StepExecutor(store)

    const result = await executor.execute({
      runId: 'run-001',
      step: 'investigator',
      attempt: 1,
      input: {
        task: 'Fix duplicate payment'
      },
      execute: () =>
        Promise.resolve({
          hypothesis: 'Duplicate insert'
        })
    })

    expect(result.inputHash).toBe(
      hashValue({
        task: 'Fix duplicate payment'
      })
    )

    expect(result.outputHash).toBe(
      hashValue({
        hypothesis: 'Duplicate insert'
      })
    )
  })

  it('resumes from a valid checkpoint', async () => {
    const store = new MemoryCheckpointStore()

    const executor = new StepExecutor(store)

    let executions = 0

    const input = {
      runId: 'run-001',
      step: 'investigator',
      attempt: 1,
      input: {
        task: 'Fix duplicate payment'
      },
      execute: () => {
        executions += 1

        return Promise.resolve({
          hypothesis: 'Duplicate insert'
        })
      }
    }

    await executor.execute(input)

    const resumed = await executor.execute(input)

    expect(resumed.resumed).toBe(true)
    expect(executions).toBe(1)
  })

  it('creates stable identifiers', () => {
    const inputHash = hashValue({
      task: 'Fix duplicate payment'
    })

    expect(
      createExecutionId('run-001', 'investigator', 1, inputHash)
    ).toBe(createExecutionId('run-001', 'investigator', 1, inputHash))
  })
})

import type {
  ExecuteStepInput,
  ExecuteStepResult,
  StepCheckpointStore
} from '~/core/execution'

import { createHash } from 'node:crypto'
import {
  ExecutionError,
  ExecutionErrorCode,
  ExecutionFailureKind
} from '~/core/execution'

export class StepExecutor {
  constructor(private readonly checkpointStore: StepCheckpointStore) {}

  async execute<TInput, TOutput>(
    input: ExecuteStepInput<TInput, TOutput>
  ): Promise<ExecuteStepResult<TOutput>> {
    const inputHash = hashValue(input.input)

    const executionId = createExecutionId(
      input.runId,
      input.step,
      input.attempt,
      inputHash
    )

    const checkpoint = await this.checkpointStore.load<TOutput>(
      input.runId,
      executionId
    )

    if (checkpoint !== null) {
      this.assertValidCheckpoint(
        checkpoint.inputHash,
        inputHash,
        checkpoint.outputHash,
        checkpoint.output
      )

      if (
        input.workspaceRevision !== undefined &&
        checkpoint.workspaceRevision !== null &&
        input.workspaceRevision !== checkpoint.workspaceRevision
      ) {
        throw new ExecutionError(
          `Checkpoint ${executionId} belongs to another workspace revision`,
          ExecutionErrorCode.stale_checkpoint,
          {
            kind: ExecutionFailureKind.non_retryable
          }
        )
      }

      return {
        executionId,
        inputHash,
        outputHash: checkpoint.outputHash,
        resumed: true,
        output: checkpoint.output
      }
    }

    const output = await input.execute()

    const outputHash = hashValue(output)

    await this.checkpointStore.save({
      runId: input.runId,
      step: input.step,
      executionId,
      inputHash,
      outputHash,
      attempt: input.attempt,
      workspaceRevision: input.workspaceRevision ?? null,
      output
    })

    return {
      executionId,
      inputHash,
      outputHash,
      resumed: false,
      output
    }
  }

  private assertValidCheckpoint(
    storedInputHash: string,
    expectedInputHash: string,
    storedOutputHash: string,
    output: unknown
  ): void {
    if (storedInputHash !== expectedInputHash) {
      throw new ExecutionError(
        'Checkpoint input hash does not match current step input',
        ExecutionErrorCode.checkpoint_input_mismatch,
        {
          kind: ExecutionFailureKind.fatal
        }
      )
    }

    if (hashValue(output) !== storedOutputHash) {
      throw new ExecutionError(
        'Checkpoint output hash verification failed',
        ExecutionErrorCode.checkpoint_corrupted,
        {
          kind: ExecutionFailureKind.fatal
        }
      )
    }
  }
}

export function createExecutionId(
  runId: string,
  step: string,
  attempt: number,
  inputHash: string
): string {
  const digest = createHash('sha256')
    .update(runId)
    .update('\0')
    .update(step)
    .update('\0')
    .update(String(attempt))
    .update('\0')
    .update(inputHash)
    .digest('hex')
    .slice(0, 24)

  return `${step}-${digest}`
}

export function hashValue(value: unknown): string {
  return `sha256:${createHash('sha256')
    .update(stableSerialize(value))
    .digest('hex')}`
}

function stableSerialize(value: unknown): string {
  return JSON.stringify(normalizeValue(value))
}

function normalizeValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(normalizeValue)
  }

  if (typeof value !== 'object' || value === null) {
    return value
  }

  const record = value as Record<string, unknown>

  const result: Record<string, unknown> = {}

  for (const key of Object.keys(record).sort()) {
    const entry = record[key]

    if (entry !== undefined) {
      result[key] = normalizeValue(entry)
    }
  }

  return result
}

import type { ProcessOperationResult } from '~/core/process'

import { describe, expect, it } from 'vitest'
import { ImplementationGate } from '~/application/implementer'
import { ImplementerErrorCode } from '~/core/implementation'
import { ProcessOperation } from '~/core/process'

const marker = 'AGENT_FIX_REPRODUCTION: expected one payment'

describe('ImplementationGate', () => {
  it('accepts a passing reproduction test', () => {
    const gate = new ImplementationGate()

    expect(() =>
      gate.assertReproductionFixed(createCommandResult(), marker)
    ).not.toThrow()
  })

  it('rejects a reproduction test that still fails', () => {
    const gate = new ImplementationGate()

    expect(() =>
      gate.assertReproductionFixed(
        createCommandResult({
          exitCode: 1,
          succeeded: false,
          stderr: marker
        }),
        marker
      )
    ).toThrowError(
      expect.objectContaining({
        code: ImplementerErrorCode.reproduction_test_failed
      })
    )
  })

  it('rejects a timed out test run', () => {
    const gate = new ImplementationGate()

    expect(() =>
      gate.assertReproductionFixed(
        createCommandResult({
          exitCode: null,
          succeeded: false,
          timedOut: true,
          signal: 'SIGTERM'
        }),
        marker
      )
    ).toThrowError(
      expect.objectContaining({
        code: ImplementerErrorCode.test_execution_failed
      })
    )
  })

  it('rejects successful output containing the failure marker', () => {
    const gate = new ImplementationGate()

    expect(() =>
      gate.assertReproductionFixed(
        createCommandResult({
          stdout: marker
        }),
        marker
      )
    ).toThrowError(
      expect.objectContaining({
        code: ImplementerErrorCode.reproduction_test_failed
      })
    )
  })
})

function createCommandResult(
  overrides: Partial<ProcessOperationResult> = {}
): ProcessOperationResult {
  return {
    executionId: 'execution-002',
    runId: 'run-001',
    workspaceRevision: 'revision-003',

    operation: ProcessOperation.run_tests,

    command: {
      executable: 'npm',
      args: ['run', 'test']
    },

    cwd: '/runs/run-001/workspace',

    startedAt: '2026-08-04T16:00:00.000Z',

    completedAt: '2026-08-04T16:00:01.000Z',

    durationMs: 1000,

    stdout: '1 test passed',
    stderr: '',

    exitCode: 0,
    signal: null,
    timedOut: false,
    succeeded: true,

    artifact: {
      id: 'execution-002',
      type: 'command.result',
      relativePath: 'commands/execution-002.json'
    },

    ...overrides
  }
}

import type { ProcessOperationResult } from '~/core/process'

import {
  ImplementerError,
  ImplementerErrorCode
} from '~/core/implementation'
import { ProcessOperation } from '~/core/process'

export class ImplementationGate {
  assertReproductionFixed(
    commandResult: ProcessOperationResult,
    expectedFailureMarker: string
  ): void {
    if (commandResult.operation !== ProcessOperation.run_tests) {
      throw new ImplementerError(
        'Implementation gate received a non-test command result',
        ImplementerErrorCode.test_execution_failed
      )
    }

    if (commandResult.timedOut) {
      throw new ImplementerError(
        'Post-implementation test run timed out',
        ImplementerErrorCode.test_execution_failed,
        {
          retryable: true
        }
      )
    }

    if (!commandResult.succeeded || commandResult.exitCode !== 0) {
      throw new ImplementerError(
        'Reproduction test still fails after implementation',
        ImplementerErrorCode.reproduction_test_failed,
        {
          retryable: true
        }
      )
    }

    const output = normalizeOutput(
      `${commandResult.stdout}\n${commandResult.stderr}`
    )

    if (output.includes(expectedFailureMarker)) {
      throw new ImplementerError(
        'Successful test output still contains the reproduction marker',
        ImplementerErrorCode.reproduction_test_failed,
        {
          retryable: true
        }
      )
    }
  }
}

function normalizeOutput(output: string): string {
  return output
    .replaceAll(
      // eslint-disable-next-line no-control-regex
      /\u001B\[[0-?]*[ -/]*[@-~]/g,
      ''
    )
    .replaceAll('\r\n', '\n')
}

import type {
  AllowedFileScope,
  ImplementationPlan,
  ReproductionFailureSnapshot
} from '~/core/implementation'

import { describe, expect, it } from 'vitest'
import { ImplementationPatchValidator } from '~/application/implementer'
import { ImplementerErrorCode } from '~/core/implementation'

const workspaceRevision = 'revision-002'

describe('ImplementationPatchValidator', () => {
  it('accepts changes inside the allowed scope', () => {
    const validator = new ImplementationPatchValidator()

    expect(
      validator.validate(
        createPlan(),
        createAllowedScope(),
        createReproduction(),
        workspaceRevision
      )
    ).toEqual(['src/payment-service.ts'])
  })

  it('rejects changes outside the allowed scope', () => {
    const validator = new ImplementationPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          changedFiles: ['src/unrelated.ts'],

          patch: createPatch('src/unrelated.ts')
        }),
        createAllowedScope(),
        createReproduction(),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ImplementerErrorCode.forbidden_file_change
      })
    )
  })

  it('rejects reproduction test changes', () => {
    const validator = new ImplementationPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          changedFiles: ['tests/payment-webhook.test.ts'],

          patch: createPatch('tests/payment-webhook.test.ts')
        }),

        {
          files: [
            'src/payment-service.ts',
            'tests/payment-webhook.test.ts'
          ],
          workspaceRevision
        },

        createReproduction(),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ImplementerErrorCode.reproduction_test_modified
      })
    )
  })

  it('rejects a stale implementation plan', () => {
    const validator = new ImplementationPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          workspaceRevision: 'revision-old'
        }),
        createAllowedScope(),
        createReproduction(),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ImplementerErrorCode.stale_workspace
      })
    )
  })

  it('rejects mismatched declared files', () => {
    const validator = new ImplementationPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          changedFiles: ['src/webhook-handler.ts']
        }),
        createAllowedScope(),
        createReproduction(),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ImplementerErrorCode.changed_files_mismatch
      })
    )
  })
})

function createAllowedScope(): AllowedFileScope {
  return {
    files: ['src/payment-service.ts', 'src/webhook-handler.ts'],
    workspaceRevision
  }
}

function createReproduction(): ReproductionFailureSnapshot {
  const marker = 'AGENT_FIX_REPRODUCTION: expected one payment'

  return {
    testFiles: ['tests/payment-webhook.test.ts'],

    expectedFailureMarker: marker,

    workspaceRevision,

    commandResult: {
      executionId: 'execution-001',
      exitCode: 1,
      timedOut: false,
      succeeded: false,
      stdout: '',
      stderr: marker
    }
  }
}

function createPlan(
  overrides: Partial<ImplementationPlan> = {}
): ImplementationPlan {
  return {
    summary: 'Add an idempotency check before inserting a payment',

    patch: createPatch('src/payment-service.ts'),

    changedFiles: ['src/payment-service.ts'],

    risks: [
      'Concurrent webhook deliveries require atomic storage semantics'
    ],

    workspaceRevision,

    ...overrides
  }
}

function createPatch(filePath: string): string {
  return [
    `diff --git a/${filePath} b/${filePath}`,
    'index 1111111..2222222 100644',
    `--- a/${filePath}`,
    `+++ b/${filePath}`,
    '@@ -1,3 +1,7 @@',
    ' export function createPayment(eventId: string) {',
    '+  if (payments.some((payment) => payment.eventId === eventId)) {',
    '+    return',
    '+  }',
    '+',
    '   return payments.push({ eventId })',
    ' }'
  ].join('\n')
}

import type {
  AllowedFileScope,
  ImplementationPlan,
  ReproductionFailureSnapshot
} from '~/core/implementation'

import {
  ImplementerError,
  ImplementerErrorCode
} from '~/core/implementation'

const diffHeaderPattern = /^diff --git a\/(.+) b\/(.+)$/gm

const forbiddenPatchMarkers = [
  'GIT binary patch',
  'Binary files ',
  'rename from ',
  'rename to ',
  'deleted file mode '
]

export class ImplementationPatchValidator {
  validate(
    plan: ImplementationPlan,
    allowedFileScope: AllowedFileScope,
    reproduction: ReproductionFailureSnapshot,
    expectedWorkspaceRevision: string
  ): readonly string[] {
    if (plan.workspaceRevision !== expectedWorkspaceRevision) {
      throw new ImplementerError(
        'Implementation patch was produced from a stale workspace',
        ImplementerErrorCode.stale_workspace,
        {
          retryable: true
        }
      )
    }

    if (allowedFileScope.workspaceRevision !== expectedWorkspaceRevision) {
      throw new ImplementerError(
        'Allowed file scope belongs to a stale workspace',
        ImplementerErrorCode.stale_workspace
      )
    }

    for (const marker of forbiddenPatchMarkers) {
      if (plan.patch.includes(marker)) {
        throw new ImplementerError(
          `Implementation patch contains forbidden marker: ${marker}`,
          ImplementerErrorCode.invalid_patch,
          {
            retryable: true
          }
        )
      }
    }

    const patchFiles = extractChangedFiles(plan.patch)

    if (patchFiles.length === 0) {
      throw new ImplementerError(
        'Implementation patch does not contain changed files',
        ImplementerErrorCode.invalid_patch,
        {
          retryable: true
        }
      )
    }

    assertSameFiles(patchFiles, plan.changedFiles)

    const allowedFiles = new Set(allowedFileScope.files)

    const reproductionTestFiles = new Set(reproduction.testFiles)

    for (const filePath of patchFiles) {
      if (!isSafeRelativePath(filePath)) {
        throw new ImplementerError(
          `Implementation patch contains unsafe path: ${filePath}`,
          ImplementerErrorCode.invalid_patch
        )
      }

      if (reproductionTestFiles.has(filePath)) {
        throw new ImplementerError(
          `Implementation patch modifies reproduction test: ${filePath}`,
          ImplementerErrorCode.reproduction_test_modified
        )
      }

      if (!allowedFiles.has(filePath)) {
        throw new ImplementerError(
          `Implementation patch changes file outside allowed scope: ` +
            filePath,
          ImplementerErrorCode.forbidden_file_change
        )
      }
    }

    return patchFiles
  }
}

function extractChangedFiles(patch: string): string[] {
  const files: string[] = []
  let match: RegExpExecArray | null

  diffHeaderPattern.lastIndex = 0

  while ((match = diffHeaderPattern.exec(patch)) !== null) {
    const sourcePath = match[1]
    const targetPath = match[2]

    if (
      sourcePath === undefined ||
      targetPath === undefined ||
      sourcePath !== targetPath
    ) {
      throw new ImplementerError(
        'Implementation patch contains a rename or invalid diff header',
        ImplementerErrorCode.invalid_patch
      )
    }

    if (!files.includes(targetPath)) {
      files.push(targetPath)
    }
  }

  return files
}

function assertSameFiles(
  patchFiles: readonly string[],
  declaredFiles: readonly string[]
): void {
  const normalizedPatchFiles = [...patchFiles].sort()

  const normalizedDeclaredFiles = [...declaredFiles].sort()

  if (normalizedPatchFiles.length !== normalizedDeclaredFiles.length) {
    throw new ImplementerError(
      'Declared changed files do not match implementation patch',
      ImplementerErrorCode.changed_files_mismatch,
      {
        retryable: true
      }
    )
  }

  for (let index = 0; index < normalizedPatchFiles.length; index += 1) {
    if (normalizedPatchFiles[index] !== normalizedDeclaredFiles[index]) {
      throw new ImplementerError(
        'Declared changed files do not match implementation patch',
        ImplementerErrorCode.changed_files_mismatch,
        {
          retryable: true
        }
      )
    }
  }
}

function isSafeRelativePath(filePath: string): boolean {
  if (
    filePath.startsWith('/') ||
    filePath.startsWith('\\') ||
    filePath.includes('\\') ||
    /^[a-zA-Z]:/.test(filePath)
  ) {
    return false
  }

  return filePath
    .split('/')
    .every(
      (segment) =>
        segment.length > 0 && segment !== '.' && segment !== '..'
    )
}

import type {
  ImplementationArtifactStore,
  ImplementationInput,
  ImplementationPlan,
  ImplementationResult,
  ImplementerAgent
} from '~/core/implementation'
import type { Logger } from '~/core/logging'
import type { ModelProvider, ModelResult } from '~/core/model'
import type {
  ProcessOperationResult,
  ProcessRunnerFactory
} from '~/core/process'
import type {
  PromptRegistry,
  PromptVersionIdentifier
} from '~/core/prompt'
import type { TraceRecorder } from '~/core/trace'
import type {
  RepositoryTools,
  RepositoryToolsFactory,
  WorkspaceSnapshot
} from '~/core/workspace'

import { z } from 'zod'
import { ImplementationGate } from '~/application/implementer/implementation-gate'
import { ImplementationPatchValidator } from '~/application/implementer/implementation-patch-validator'
import { AgentRole } from '~/core/context'
import {
  ImplementerError,
  ImplementerErrorCode,
  implementationInputSchema,
  implementationPlanSchema
} from '~/core/implementation'
import { TraceEventType } from '~/core/trace'

const implementerStep = 'implementer'

export class ModelImplementerAgent implements ImplementerAgent {
  constructor(
    private readonly modelProvider: ModelProvider,
    private readonly promptRegistry: PromptRegistry,
    private readonly repositoryToolsFactory: RepositoryToolsFactory,
    private readonly processRunnerFactory: ProcessRunnerFactory,
    private readonly artifactStore: ImplementationArtifactStore,
    private readonly traceRecorder: TraceRecorder,
    private readonly logger: Logger,
    private readonly patchValidator = new ImplementationPatchValidator(),
    private readonly implementationGate = new ImplementationGate()
  ) {}

  async execute(
    input: ImplementationInput
  ): Promise<ImplementationResult> {
    this.assertValidInput(input)

    const sourceWorkspaceRevision = input.context.context.workspaceRevision

    const logger = this.logger.child({
      runId: input.context.context.runId,
      step: implementerStep,
      agent: AgentRole.implementer,
      workspaceRevision: sourceWorkspaceRevision
    })

    let promptVersion: PromptVersionIdentifier | undefined

    try {
      const prompt = await this.promptRegistry.load(AgentRole.implementer)

      promptVersion = prompt.id

      const repositoryTools = this.repositoryToolsFactory.create(
        input.workspace
      )

      await this.assertFreshWorkspace(
        repositoryTools,
        sourceWorkspaceRevision
      )

      const modelResult = await this.modelProvider.generate({
        input: [
          {
            type: 'message',
            role: 'system',
            content: prompt.content
          },
          {
            type: 'message',
            role: 'user',
            content: JSON.stringify({
              context: {
                runId: input.context.context.runId,
                task: input.context.context.task,
                workspaceRevision: sourceWorkspaceRevision,
                constraints: input.context.context.constraints
              },

              confirmedEvidence: input.evidence,

              failingTest: {
                testFiles: input.reproduction.testFiles,
                expectedFailureMarker:
                  input.reproduction.expectedFailureMarker,
                workspaceRevision: input.reproduction.workspaceRevision,
                commandResult: input.reproduction.commandResult
              },

              allowedFileScope: input.allowedFileScope
            })
          }
        ],
        outputSchemaName: 'implementation_plan',
        outputSchema: implementationPlanSchema
      })

      await this.recordModelCall(input, prompt.id, modelResult)

      if (modelResult.toolCalls.length > 0) {
        throw new ImplementerError(
          'Implementer returned an unexpected tool call',
          ImplementerErrorCode.unexpected_tool_call
        )
      }

      if (modelResult.output === undefined) {
        throw new ImplementerError(
          'Implementer returned no structured output',
          ImplementerErrorCode.missing_output,
          {
            retryable: true
          }
        )
      }

      const plan = this.parsePlan(modelResult.output)

      const expectedChangedFiles = this.patchValidator.validate(
        plan,
        input.allowedFileScope,
        input.reproduction,
        sourceWorkspaceRevision
      )

      await this.assertFreshWorkspace(
        repositoryTools,
        sourceWorkspaceRevision
      )

      const applyResult = await this.applyPatch(
        input,
        prompt.id,
        repositoryTools,
        plan
      )

      assertChangedFilesMatch(
        expectedChangedFiles,
        applyResult.changedFiles
      )

      assertReproductionTestsUnchanged(
        applyResult.changedFiles,
        input.reproduction.testFiles
      )

      const patchedWorkspace: WorkspaceSnapshot = {
        ...input.workspace,
        workspaceRevision: applyResult.workspaceRevision
      }

      const processRunner =
        this.processRunnerFactory.create(patchedWorkspace)

      const commandResult = await this.runTests(
        input,
        prompt.id,
        processRunner.runTests.bind(processRunner),
        applyResult.workspaceRevision
      )

      this.implementationGate.assertReproductionFixed(
        commandResult,
        input.reproduction.expectedFailureMarker
      )

      const artifacts = await this.artifactStore.save({
        runId: input.context.context.runId,
        plan,
        sourceWorkspaceRevision,
        workspaceRevision: applyResult.workspaceRevision,
        reproduction: input.reproduction,
        commandResult
      })

      const result: ImplementationResult = {
        summary: plan.summary,
        patch: plan.patch,
        changedFiles: plan.changedFiles,
        risks: plan.risks,
        sourceWorkspaceRevision,
        workspaceRevision: applyResult.workspaceRevision,
        commandResult,
        artifacts
      }

      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: implementerStep,
        agent: AgentRole.implementer,
        workspaceRevision: result.workspaceRevision,
        type: TraceEventType.agent_result,
        promptVersion: prompt.id,
        output: {
          summary: result.summary,
          changedFiles: result.changedFiles,
          risks: result.risks,
          implementationArtifact: result.artifacts.implementation,
          patchArtifact: result.artifacts.patch,
          commandArtifact: result.artifacts.command
        }
      })

      logger.info('Implementation completed', {
        changedFiles: result.changedFiles,
        commandExecutionId: commandResult.executionId
      })

      return result
    } catch (error) {
      await this.recordFailure(input, promptVersion, error, logger)

      logger.error('Implementation failed', {
        error
      })

      throw error
    }
  }

  private assertValidInput(input: ImplementationInput): void {
    const result = implementationInputSchema.safeParse(input)

    if (!result.success) {
      throw new ImplementerError(
        'Implementation input failed schema validation: ' +
          z.prettifyError(result.error),
        ImplementerErrorCode.invalid_input,
        {
          cause: result.error
        }
      )
    }
  }

  private parsePlan(value: unknown): ImplementationPlan {
    const result = implementationPlanSchema.safeParse(value)

    if (!result.success) {
      throw new ImplementerError(
        'Implementation output failed schema validation: ' +
          z.prettifyError(result.error),
        ImplementerErrorCode.invalid_output,
        {
          retryable: true,
          cause: result.error
        }
      )
    }

    return result.data
  }

  private async assertFreshWorkspace(
    repositoryTools: RepositoryTools,
    expectedRevision: string
  ): Promise<void> {
    const currentRevision = await repositoryTools.getWorkspaceRevision()

    if (currentRevision !== expectedRevision) {
      throw new ImplementerError(
        'Implementer context contains a stale workspace revision',
        ImplementerErrorCode.stale_workspace,
        {
          retryable: true
        }
      )
    }
  }

  private async applyPatch(
    input: ImplementationInput,
    promptVersion: PromptVersionIdentifier,
    repositoryTools: RepositoryTools,
    plan: ImplementationPlan
  ) {
    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: implementerStep,
      agent: AgentRole.implementer,
      workspaceRevision: input.workspace.workspaceRevision,
      type: TraceEventType.tool_call,
      promptVersion,
      input: {
        name: 'applyImplementationPatch',
        changedFiles: plan.changedFiles
      }
    })

    try {
      const result = await repositoryTools.applyPatch(plan.patch)

      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: implementerStep,
        agent: AgentRole.implementer,
        workspaceRevision: result.workspaceRevision,
        type: TraceEventType.tool_result,
        promptVersion,
        output: {
          name: 'applyImplementationPatch',
          changedFiles: result.changedFiles,
          workspaceRevision: result.workspaceRevision
        }
      })

      return result
    } catch (error) {
      throw new ImplementerError(
        'Failed to apply implementation patch',
        ImplementerErrorCode.patch_application_failed,
        {
          retryable: true,
          cause: error
        }
      )
    }
  }

  private async runTests(
    input: ImplementationInput,
    promptVersion: PromptVersionIdentifier,
    runTests: () => Promise<ProcessOperationResult>,
    workspaceRevision: string
  ): Promise<ProcessOperationResult> {
    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: implementerStep,
      agent: AgentRole.implementer,
      workspaceRevision,
      type: TraceEventType.tool_call,
      promptVersion,
      input: {
        name: 'runTests'
      }
    })

    const result = await runTests()

    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: implementerStep,
      agent: AgentRole.implementer,
      workspaceRevision,
      type: TraceEventType.tool_result,
      promptVersion,
      durationMs: result.durationMs,
      output: {
        name: 'runTests',
        executionId: result.executionId,
        exitCode: result.exitCode,
        signal: result.signal,
        timedOut: result.timedOut,
        succeeded: result.succeeded,
        artifact: result.artifact
      }
    })

    return result
  }

  private recordModelCall(
    input: ImplementationInput,
    promptVersion: PromptVersionIdentifier,
    result: ModelResult<ImplementationPlan>
  ): Promise<void> {
    return this.traceRecorder.record({
      runId: input.context.context.runId,
      step: implementerStep,
      agent: AgentRole.implementer,
      workspaceRevision: input.workspace.workspaceRevision,
      type: TraceEventType.agent_call,
      promptVersion,
      durationMs: result.durationMs,
      tokenUsage: result.usage,
      output: {
        returnedStructuredOutput: result.output !== undefined,
        toolCalls: result.toolCalls.map((toolCall) => toolCall.name)
      }
    })
  }

  private async recordFailure(
    input: ImplementationInput,
    promptVersion: PromptVersionIdentifier | undefined,
    error: unknown,
    logger: Logger
  ): Promise<void> {
    try {
      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: implementerStep,
        agent: AgentRole.implementer,
        workspaceRevision: input.context.context.workspaceRevision,
        type: TraceEventType.failure,
        error: toTraceError(error),

        ...(promptVersion === undefined
          ? {}
          : {
              promptVersion
            })
      })
    } catch (traceError) {
      logger.warn('Failed to record implementer failure', {
        traceError
      })
    }
  }
}

function assertChangedFilesMatch(
  expectedFiles: readonly string[],
  actualFiles: readonly string[]
): void {
  const expected = [...expectedFiles].sort()

  const actual = [...actualFiles].sort()

  if (expected.length !== actual.length) {
    throw new ImplementerError(
      'Applied implementation patch changed unexpected files',
      ImplementerErrorCode.changed_files_mismatch
    )
  }

  for (let index = 0; index < expected.length; index += 1) {
    if (expected[index] !== actual[index]) {
      throw new ImplementerError(
        'Applied implementation patch changed unexpected files',
        ImplementerErrorCode.changed_files_mismatch
      )
    }
  }
}

function assertReproductionTestsUnchanged(
  changedFiles: readonly string[],
  reproductionTestFiles: readonly string[]
): void {
  const testFiles = new Set(reproductionTestFiles)

  const changedTest = changedFiles.find((filePath) =>
    testFiles.has(filePath)
  )

  if (changedTest !== undefined) {
    throw new ImplementerError(
      `Implementation modified reproduction test: ${changedTest}`,
      ImplementerErrorCode.reproduction_test_modified
    )
  }
}

function toTraceError(error: unknown): {
  name: string
  message: string
  code?: string
  retryable?: boolean
} {
  if (!(error instanceof Error)) {
    return {
      name: 'UnknownError',
      message: 'Unknown implementer failure'
    }
  }

  const result: {
    name: string
    message: string
    code?: string
    retryable?: boolean
  } = {
    name: error.name,
    message: error.message
  }

  if ('code' in error && typeof error.code === 'string') {
    result.code = error.code
  }

  if ('retryable' in error && typeof error.retryable === 'boolean') {
    result.retryable = error.retryable
  }

  return result
}

import type { InvestigationResult } from '~/core/investigation'
import type { RepositoryTools } from '~/core/workspace'

import { z } from 'zod'
import {
  InvestigatorError,
  InvestigatorErrorCode,
  investigationResultSchema
} from '~/core/investigation'

export class InvestigationValidator {
  async validate(
    result: unknown,
    expectedWorkspaceRevision: string,
    repositoryTools: RepositoryTools
  ): Promise<InvestigationResult> {
    const schemaResult = investigationResultSchema.safeParse(result)

    if (!schemaResult.success) {
      throw new InvestigatorError(
        'Investigation result failed schema validation: ' +
          z.prettifyError(schemaResult.error),
        InvestigatorErrorCode.invalid_output,
        {
          retryable: true,
          cause: schemaResult.error
        }
      )
    }

    const investigation = schemaResult.data

    await this.assertFreshWorkspace(
      investigation,
      expectedWorkspaceRevision,
      repositoryTools
    )

    const repositoryFiles = await repositoryTools.listFiles()

    const existingFiles = new Set(repositoryFiles.map((file) => file.path))

    for (const filePath of investigation.relatedFiles) {
      if (!existingFiles.has(filePath)) {
        throw new InvestigatorError(
          `Investigator referenced a missing file: ${filePath}`,
          InvestigatorErrorCode.hallucinated_file,
          {
            retryable: true
          }
        )
      }
    }

    const fileContents = new Map<string, string>()

    for (const evidence of investigation.evidence) {
      if (!existingFiles.has(evidence.filePath)) {
        throw new InvestigatorError(
          `Evidence references a missing file: ` + evidence.filePath,
          InvestigatorErrorCode.hallucinated_file,
          {
            retryable: true
          }
        )
      }

      const content = await this.getFileContent(
        evidence.filePath,
        repositoryTools,
        fileContents
      )

      this.assertLineRange(
        evidence.filePath,
        evidence.lineStart,
        evidence.lineEnd,
        content
      )

      this.assertSymbolExists(
        evidence.filePath,
        evidence.symbol,
        evidence.lineStart,
        evidence.lineEnd,
        content
      )
    }

    this.assertGroundedHypothesis(investigation)

    return investigation
  }

  private async assertFreshWorkspace(
    result: InvestigationResult,
    expectedWorkspaceRevision: string,
    repositoryTools: RepositoryTools
  ): Promise<void> {
    if (result.workspaceRevision !== expectedWorkspaceRevision) {
      throw new InvestigatorError(
        'Investigation result was produced from a stale workspace',
        InvestigatorErrorCode.stale_workspace,
        {
          retryable: true
        }
      )
    }

    const currentWorkspaceRevision =
      await repositoryTools.getWorkspaceRevision()

    if (currentWorkspaceRevision !== expectedWorkspaceRevision) {
      throw new InvestigatorError(
        'Workspace changed during investigation',
        InvestigatorErrorCode.stale_workspace,
        {
          retryable: true
        }
      )
    }
  }

  private async getFileContent(
    filePath: string,
    repositoryTools: RepositoryTools,
    cache: Map<string, string>
  ): Promise<string> {
    const cachedContent = cache.get(filePath)

    if (cachedContent !== undefined) {
      return cachedContent
    }

    const file = await repositoryTools.readFile(filePath)

    cache.set(filePath, file.content)

    return file.content
  }

  private assertLineRange(
    filePath: string,
    lineStart: number,
    lineEnd: number,
    content: string
  ): void {
    const lineCount = content.split(/\r?\n/).length

    if (
      lineStart > lineCount ||
      lineEnd > lineCount ||
      lineEnd < lineStart
    ) {
      throw new InvestigatorError(
        `Evidence contains an invalid line range for ` +
          `${filePath}: ${lineStart}-${lineEnd}`,
        InvestigatorErrorCode.invalid_line_range,
        {
          retryable: true
        }
      )
    }
  }

  private assertSymbolExists(
    filePath: string,
    symbol: string,
    lineStart: number,
    lineEnd: number,
    content: string
  ): void {
    const selectedContent = content
      .split(/\r?\n/)
      .slice(lineStart - 1, lineEnd)
      .join('\n')

    const symbolPattern = new RegExp(
      `(^|[^a-zA-Z0-9_$])${escapeRegularExpression(symbol)}` +
        `([^a-zA-Z0-9_$]|$)`
    )

    if (!symbolPattern.test(selectedContent)) {
      throw new InvestigatorError(
        `Investigator referenced missing symbol ${symbol} ` +
          `at ${filePath}:${lineStart}-${lineEnd}`,
        InvestigatorErrorCode.hallucinated_symbol,
        {
          retryable: true
        }
      )
    }
  }

  private assertGroundedHypothesis(result: InvestigationResult): void {
    const normalizedHypothesis = result.hypothesis.toLowerCase()

    const referencesKnownSymbol = result.evidence.some((evidence) =>
      normalizedHypothesis.includes(evidence.symbol.toLowerCase())
    )

    if (!referencesKnownSymbol) {
      throw new InvestigatorError(
        'Bug hypothesis does not reference any confirmed symbol',
        InvestigatorErrorCode.ungrounded_hypothesis,
        {
          retryable: true
        }
      )
    }
  }
}

function escapeRegularExpression(value: string): string {
  return value.replaceAll(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

