import type {
  InvestigationInput,
  InvestigationResult,
  InvestigatorAgent
} from '~/core/investigation'
import type { Logger } from '~/core/logging'
import type {
  ModelInput,
  ModelProvider,
  ModelResult,
  ModelToolResult
} from '~/core/model'
import type {
  PromptRegistry,
  PromptVersionIdentifier
} from '~/core/prompt'
import type { TraceRecorder } from '~/core/trace'
import type {
  RepositoryTools,
  RepositoryToolsFactory
} from '~/core/workspace'

import { z } from 'zod'
import { InvestigationValidator } from '~/application/investigator/investigation-validator'
import { InvestigatorRepositoryTools } from '~/application/investigator/investigator-tools'
import { AgentRole } from '~/core/context'
import {
  InvestigatorError,
  InvestigatorErrorCode,
  investigationInputSchema,
  investigationResultSchema
} from '~/core/investigation'
import { TraceEventType } from '~/core/trace'

const investigatorStep = 'investigator'

export interface ModelInvestigatorAgentOptions {
  readonly maximumToolIterations?: number
}

export class ModelInvestigatorAgent implements InvestigatorAgent {
  private readonly maximumToolIterations: number

  constructor(
    private readonly modelProvider: ModelProvider,
    private readonly promptRegistry: PromptRegistry,
    private readonly repositoryToolsFactory: RepositoryToolsFactory,
    private readonly traceRecorder: TraceRecorder,
    private readonly logger: Logger,
    private readonly validator = new InvestigationValidator(),
    options: ModelInvestigatorAgentOptions = {}
  ) {
    const maximumToolIterations = options.maximumToolIterations ?? 20

    if (
      !Number.isInteger(maximumToolIterations) ||
      maximumToolIterations <= 0
    ) {
      throw new Error('maximumToolIterations must be a positive integer')
    }

    this.maximumToolIterations = maximumToolIterations
  }

  async execute(input: InvestigationInput): Promise<InvestigationResult> {
    this.assertValidInput(input)

    const expectedWorkspaceRevision =
      input.context.context.workspaceRevision

    const logger = this.logger.child({
      runId: input.context.context.runId,
      step: investigatorStep,
      agent: AgentRole.investigator,
      workspaceRevision: expectedWorkspaceRevision
    })

    let promptVersion: PromptVersionIdentifier | undefined

    try {
      const prompt = await this.promptRegistry.load(AgentRole.investigator)

      promptVersion = prompt.id

      const repositoryTools = this.repositoryToolsFactory.create(
        input.workspace
      )

      await this.assertInitialWorkspaceRevision(
        expectedWorkspaceRevision,
        repositoryTools
      )

      const investigatorTools = new InvestigatorRepositoryTools(
        repositoryTools
      )

      let modelInput: readonly ModelInput[] = [
        {
          type: 'message',
          role: 'system',
          content: prompt.content
        },
        {
          type: 'message',
          role: 'user',
          content: JSON.stringify({
            agentContext: input.context.context
          })
        }
      ]

      let previousResponseId: string | undefined

      for (
        let iteration = 1;
        iteration <= this.maximumToolIterations;
        iteration += 1
      ) {
        const modelResult = await this.modelProvider.generate({
          input: modelInput,
          outputSchemaName: 'investigation_result',
          outputSchema: investigationResultSchema,
          tools: investigatorTools.definitions,

          ...(previousResponseId === undefined
            ? {}
            : {
                previousResponseId
              })
        })

        await this.recordModelCall(
          input,
          prompt.id,
          iteration,
          modelResult
        )

        if (modelResult.toolCalls.length > 0) {
          if (modelResult.responseId === undefined) {
            throw new InvestigatorError(
              'Model returned tool calls without a response identifier',
              InvestigatorErrorCode.missing_response_id,
              {
                retryable: true
              }
            )
          }

          modelInput = await this.executeToolCalls(
            input,
            prompt.id,
            investigatorTools,
            modelResult.toolCalls
          )

          previousResponseId = modelResult.responseId

          continue
        }

        if (modelResult.output === undefined) {
          throw new InvestigatorError(
            'Investigator returned no structured output',
            InvestigatorErrorCode.missing_output,
            {
              retryable: true
            }
          )
        }

        const investigation = await this.validator.validate(
          modelResult.output,
          expectedWorkspaceRevision,
          repositoryTools
        )

        await this.traceRecorder.record({
          runId: input.context.context.runId,
          step: investigatorStep,
          agent: AgentRole.investigator,
          workspaceRevision: expectedWorkspaceRevision,
          type: TraceEventType.agent_result,
          promptVersion: prompt.id,
          output: investigation
        })

        logger.info('Investigation completed', {
          evidenceCount: investigation.evidence.length,
          relatedFileCount: investigation.relatedFiles.length
        })

        return investigation
      }

      throw new InvestigatorError(
        `Investigator exceeded ${this.maximumToolIterations} ` +
          'tool iterations',
        InvestigatorErrorCode.tool_loop_exhausted,
        {
          retryable: true
        }
      )
    } catch (error) {
      await this.recordFailure(input, promptVersion, error, logger)

      logger.error('Investigation failed', {
        error
      })

      throw error
    }
  }

  private assertValidInput(input: InvestigationInput): void {
    const result = investigationInputSchema.safeParse(input)

    if (!result.success) {
      throw new InvestigatorError(
        'Investigation input failed schema validation: ' +
          z.prettifyError(result.error),
        InvestigatorErrorCode.invalid_input,
        {
          cause: result.error
        }
      )
    }
  }

  private async assertInitialWorkspaceRevision(
    expectedRevision: string,
    repositoryTools: RepositoryTools
  ): Promise<void> {
    const currentRevision = await repositoryTools.getWorkspaceRevision()

    if (currentRevision !== expectedRevision) {
      throw new InvestigatorError(
        'Investigator context contains a stale workspace revision',
        InvestigatorErrorCode.stale_workspace,
        {
          retryable: true
        }
      )
    }
  }

  private async executeToolCalls(
    input: InvestigationInput,
    promptVersion: PromptVersionIdentifier,
    tools: InvestigatorRepositoryTools,
    toolCalls: ModelResult<InvestigationResult>['toolCalls']
  ): Promise<readonly ModelToolResult[]> {
    const toolResults: ModelToolResult[] = []

    for (const toolCall of toolCalls) {
      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: investigatorStep,
        agent: AgentRole.investigator,
        workspaceRevision: input.context.context.workspaceRevision,
        type: TraceEventType.tool_call,
        promptVersion,
        input: {
          callId: toolCall.id,
          name: toolCall.name,
          arguments: toolCall.arguments
        }
      })

      const toolResult = await tools.execute(toolCall)

      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: investigatorStep,
        agent: AgentRole.investigator,
        workspaceRevision: input.context.context.workspaceRevision,
        type: TraceEventType.tool_result,
        promptVersion,
        output: {
          callId: toolCall.id,
          name: toolCall.name,
          result: toolResult.traceOutput
        }
      })

      toolResults.push({
        type: 'tool_result',
        callId: toolCall.id,
        output: toolResult.modelOutput
      })
    }

    return toolResults
  }

  private recordModelCall(
    input: InvestigationInput,
    promptVersion: PromptVersionIdentifier,
    iteration: number,
    result: ModelResult<InvestigationResult>
  ): Promise<void> {
    return this.traceRecorder.record({
      runId: input.context.context.runId,
      step: investigatorStep,
      agent: AgentRole.investigator,
      workspaceRevision: input.context.context.workspaceRevision,
      type: TraceEventType.agent_call,
      promptVersion,
      durationMs: result.durationMs,
      tokenUsage: result.usage,
      input: {
        iteration
      },
      output: {
        returnedStructuredOutput: result.output !== undefined,

        toolCalls: result.toolCalls.map((toolCall) => toolCall.name)
      }
    })
  }

  private async recordFailure(
    input: InvestigationInput,
    promptVersion: PromptVersionIdentifier | undefined,
    error: unknown,
    logger: Logger
  ): Promise<void> {
    try {
      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: investigatorStep,
        agent: AgentRole.investigator,
        workspaceRevision: input.context.context.workspaceRevision,
        type: TraceEventType.failure,
        error: toTraceError(error),

        ...(promptVersion === undefined
          ? {}
          : {
              promptVersion
            })
      })
    } catch (traceError) {
      logger.warn('Failed to record investigator failure', {
        traceError
      })
    }
  }
}

function toTraceError(error: unknown): {
  name: string
  message: string
  code?: string
  retryable?: boolean
} {
  if (!(error instanceof Error)) {
    return {
      name: 'UnknownError',
      message: 'Unknown investigator failure'
    }
  }

  const result: {
    name: string
    message: string
    code?: string
    retryable?: boolean
  } = {
    name: error.name,
    message: error.message
  }

  if ('code' in error && typeof error.code === 'string') {
    result.code = error.code
  }

  if ('retryable' in error && typeof error.retryable === 'boolean') {
    result.retryable = error.retryable
  }

  return result
}

import type { ModelTool, ModelToolCall } from '~/core/model'
import type { RepositoryTools } from '~/core/workspace'

import { z } from 'zod'
import {
  InvestigatorError,
  InvestigatorErrorCode
} from '~/core/investigation'

const listFilesInputSchema = z.object({}).strict()

const searchCodeInputSchema = z
  .object({
    query: z.string().trim().min(1).max(500),

    caseSensitive: z.boolean().optional(),

    maxResults: z.number().int().min(1).max(100).optional()
  })
  .strict()

const readFileInputSchema = z
  .object({
    path: z.string().trim().min(1).max(500),

    lineStart: z.number().int().positive().optional(),

    lineEnd: z.number().int().positive().optional()
  })
  .strict()
  .superRefine((input, context) => {
    if (
      input.lineStart !== undefined &&
      input.lineEnd !== undefined &&
      input.lineEnd < input.lineStart
    ) {
      context.addIssue({
        code: 'custom',
        path: ['lineEnd'],
        message: 'lineEnd must be greater than or equal to lineStart'
      })
    }

    if (
      input.lineStart !== undefined &&
      input.lineEnd !== undefined &&
      input.lineEnd - input.lineStart > 399
    ) {
      context.addIssue({
        code: 'custom',
        path: ['lineEnd'],
        message: 'A single readFile call is limited to 400 lines'
      })
    }
  })

const getWorkspaceRevisionInputSchema = z.object({}).strict()

const investigatorTools: readonly ModelTool[] = [
  {
    name: 'listFiles',
    description:
      'List readable repository files inside the isolated workspace.',
    inputSchema: listFilesInputSchema
  },
  {
    name: 'searchCode',
    description: 'Search repository source lines for an exact text query.',
    inputSchema: searchCodeInputSchema
  },
  {
    name: 'readFile',
    description: 'Read up to 400 lines from one repository-relative file.',
    inputSchema: readFileInputSchema
  },
  {
    name: 'getWorkspaceRevision',
    description:
      'Return the current immutable workspace revision identifier.',
    inputSchema: getWorkspaceRevisionInputSchema
  }
]

export interface InvestigatorToolExecutionResult {
  readonly modelOutput: string
  readonly traceOutput: unknown
}

export class InvestigatorRepositoryTools {
  readonly definitions = investigatorTools

  constructor(private readonly repositoryTools: RepositoryTools) {}

  async execute(
    toolCall: ModelToolCall
  ): Promise<InvestigatorToolExecutionResult> {
    switch (toolCall.name) {
      case 'listFiles':
        return this.listFiles(toolCall.arguments)

      case 'searchCode':
        return this.searchCode(toolCall.arguments)

      case 'readFile':
        return this.readFile(toolCall.arguments)

      case 'getWorkspaceRevision':
        return this.getWorkspaceRevision(toolCall.arguments)

      default:
        throw new InvestigatorError(
          `Unsupported investigator tool: ${toolCall.name}`,
          InvestigatorErrorCode.unsupported_tool
        )
    }
  }

  private async listFiles(
    argumentsValue: unknown
  ): Promise<InvestigatorToolExecutionResult> {
    parseToolArguments(listFilesInputSchema, argumentsValue, 'listFiles')

    const files = await this.repositoryTools.listFiles()

    const output = {
      files,
      totalFiles: files.length
    }

    return {
      modelOutput: JSON.stringify(output),
      traceOutput: output
    }
  }

  private async searchCode(
    argumentsValue: unknown
  ): Promise<InvestigatorToolExecutionResult> {
    const input = parseToolArguments(
      searchCodeInputSchema,
      argumentsValue,
      'searchCode'
    )

    const matches = await this.repositoryTools.searchCode({
      query: input.query,

      ...(input.caseSensitive === undefined
        ? {}
        : {
            caseSensitive: input.caseSensitive
          }),

      ...(input.maxResults === undefined
        ? {}
        : {
            maxResults: input.maxResults
          })
    })

    const output = {
      query: input.query,
      matches,
      totalMatches: matches.length
    }

    return {
      modelOutput: JSON.stringify(output),
      traceOutput: output
    }
  }

  private async readFile(
    argumentsValue: unknown
  ): Promise<InvestigatorToolExecutionResult> {
    const input = parseToolArguments(
      readFileInputSchema,
      argumentsValue,
      'readFile'
    )

    const file = await this.repositoryTools.readFile(input.path)
    const lines = file.content.split(/\r?\n/)

    const lineStart = input.lineStart ?? 1

    if (lineStart > lines.length) {
      throw new InvestigatorError(
        `readFile lineStart ${lineStart} exceeds ` +
          `${lines.length} lines in ${input.path}`,
        InvestigatorErrorCode.invalid_tool_arguments,
        {
          retryable: true
        }
      )
    }

    const requestedLineEnd = input.lineEnd ?? lineStart + 399

    const lineEnd = Math.min(requestedLineEnd, lines.length)

    const content = lines.slice(lineStart - 1, lineEnd).join('\n')

    const output = {
      path: file.path,
      sizeBytes: file.sizeBytes,
      lineStart,
      lineEnd,
      totalLines: lines.length,
      truncated: lineStart > 1 || lineEnd < lines.length,
      content
    }

    return {
      modelOutput: JSON.stringify(output),
      traceOutput: output
    }
  }

  private async getWorkspaceRevision(
    argumentsValue: unknown
  ): Promise<InvestigatorToolExecutionResult> {
    parseToolArguments(
      getWorkspaceRevisionInputSchema,
      argumentsValue,
      'getWorkspaceRevision'
    )

    const workspaceRevision =
      await this.repositoryTools.getWorkspaceRevision()

    const output = {
      workspaceRevision
    }

    return {
      modelOutput: JSON.stringify(output),
      traceOutput: output
    }
  }
}

function parseToolArguments<TOutput>(
  schema: z.ZodType<TOutput>,
  value: unknown,
  toolName: string
): TOutput {
  const result = schema.safeParse(value)

  if (!result.success) {
    throw new InvestigatorError(
      `Invalid arguments for ${toolName}: ` +
        z.prettifyError(result.error),
      InvestigatorErrorCode.invalid_tool_arguments,
      {
        retryable: true,
        cause: result.error
      }
    )
  }

  return result.data
}

import type { Logger } from '~/core/logging'
import type { ModelProvider, ModelResult } from '~/core/model'
import type {
  ProcessOperationResult,
  ProcessRunnerFactory
} from '~/core/process'
import type {
  PromptRegistry,
  PromptVersionIdentifier
} from '~/core/prompt'
import type {
  ReproductionArtifactStore,
  ReproductionInput,
  ReproductionPlan,
  ReproductionResult,
  ReproducerAgent
} from '~/core/reproduction'
import type { TraceRecorder } from '~/core/trace'
import type {
  RepositoryTools,
  RepositoryToolsFactory,
  WorkspaceSnapshot
} from '~/core/workspace'

import { z } from 'zod'
import { ReproductionGate } from '~/application/reproducer/reproduction-gate'
import { ReproductionPatchValidator } from '~/application/reproducer/reproduction-patch-validator'
import { TestStructureInspector } from '~/application/reproducer/test-structure-inspector'
import { AgentRole } from '~/core/context'
import {
  ReproducerError,
  ReproducerErrorCode,
  reproductionInputSchema,
  reproductionPlanSchema
} from '~/core/reproduction'
import { TraceEventType } from '~/core/trace'

const reproducerStep = 'reproducer'

export class ModelReproducerAgent implements ReproducerAgent {
  constructor(
    private readonly modelProvider: ModelProvider,
    private readonly promptRegistry: PromptRegistry,
    private readonly repositoryToolsFactory: RepositoryToolsFactory,
    private readonly processRunnerFactory: ProcessRunnerFactory,
    private readonly artifactStore: ReproductionArtifactStore,
    private readonly traceRecorder: TraceRecorder,
    private readonly logger: Logger,
    private readonly testStructureInspector = new TestStructureInspector(),
    private readonly patchValidator = new ReproductionPatchValidator(),
    private readonly reproductionGate = new ReproductionGate()
  ) {}

  async execute(input: ReproductionInput): Promise<ReproductionResult> {
    this.assertValidInput(input)

    const sourceWorkspaceRevision = input.context.context.workspaceRevision

    const logger = this.logger.child({
      runId: input.context.context.runId,
      step: reproducerStep,
      agent: AgentRole.reproducer,
      workspaceRevision: sourceWorkspaceRevision
    })

    let promptVersion: PromptVersionIdentifier | undefined

    try {
      const prompt = await this.promptRegistry.load(AgentRole.reproducer)

      promptVersion = prompt.id

      const repositoryTools = this.repositoryToolsFactory.create(
        input.workspace
      )

      await this.assertFreshWorkspace(
        repositoryTools,
        sourceWorkspaceRevision
      )

      const testStructure = await this.inspectTestStructure(
        input,
        prompt.id,
        repositoryTools,
        sourceWorkspaceRevision
      )

      const modelResult = await this.modelProvider.generate({
        input: [
          {
            type: 'message',
            role: 'system',
            content: prompt.content
          },
          {
            type: 'message',
            role: 'user',
            content: JSON.stringify({
              agentContext: input.context.context,
              investigation: input.investigation,
              testStructure
            })
          }
        ],
        outputSchemaName: 'reproduction_plan',
        outputSchema: reproductionPlanSchema
      })

      await this.recordModelCall(input, prompt.id, modelResult)

      if (modelResult.toolCalls.length > 0) {
        throw new ReproducerError(
          'Reproducer returned an unexpected tool call',
          ReproducerErrorCode.unexpected_tool_call
        )
      }

      if (modelResult.output === undefined) {
        throw new ReproducerError(
          'Reproducer returned no structured output',
          ReproducerErrorCode.missing_output,
          {
            retryable: true
          }
        )
      }

      const plan = this.parsePlan(modelResult.output)

      const patchFiles = this.patchValidator.validate(
        plan,
        sourceWorkspaceRevision
      )

      await this.assertFreshWorkspace(
        repositoryTools,
        sourceWorkspaceRevision
      )

      const applyResult = await this.applyPatch(
        input,
        prompt.id,
        repositoryTools,
        plan
      )

      assertChangedFilesMatch(patchFiles, applyResult.changedFiles)

      const patchedWorkspace: WorkspaceSnapshot = {
        ...input.workspace,
        workspaceRevision: applyResult.workspaceRevision
      }

      const processRunner =
        this.processRunnerFactory.create(patchedWorkspace)

      const commandResult = await this.runTests(
        input,
        prompt.id,
        processRunner.runTests.bind(processRunner),
        applyResult.workspaceRevision
      )

      this.reproductionGate.assertExpectedFailure(
        commandResult,
        plan.expectedFailureMarker
      )

      const artifacts = await this.artifactStore.save({
        runId: input.context.context.runId,
        plan,
        sourceWorkspaceRevision,
        workspaceRevision: applyResult.workspaceRevision,
        commandResult
      })

      const result: ReproductionResult = {
        summary: plan.summary,
        patch: plan.patch,
        testFiles: plan.testFiles,
        expectedFailureMarker: plan.expectedFailureMarker,
        sourceWorkspaceRevision,
        workspaceRevision: applyResult.workspaceRevision,
        commandResult,
        artifacts
      }

      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: reproducerStep,
        agent: AgentRole.reproducer,
        workspaceRevision: applyResult.workspaceRevision,
        type: TraceEventType.agent_result,
        promptVersion: prompt.id,
        output: {
          summary: result.summary,
          testFiles: result.testFiles,
          expectedFailureMarker: result.expectedFailureMarker,
          commandArtifact: result.commandResult.artifact,
          reproductionArtifact: result.artifacts.reproduction,
          patchArtifact: result.artifacts.patch
        }
      })

      logger.info('Reproduction confirmed', {
        testFiles: result.testFiles,
        commandExecutionId: commandResult.executionId
      })

      return result
    } catch (error) {
      await this.recordFailure(input, promptVersion, error, logger)

      logger.error('Reproduction failed', {
        error
      })

      throw error
    }
  }

  private assertValidInput(input: ReproductionInput): void {
    const result = reproductionInputSchema.safeParse(input)

    if (!result.success) {
      throw new ReproducerError(
        'Reproduction input failed schema validation: ' +
          z.prettifyError(result.error),
        ReproducerErrorCode.invalid_input,
        {
          cause: result.error
        }
      )
    }
  }

  private parsePlan(value: unknown): ReproductionPlan {
    const result = reproductionPlanSchema.safeParse(value)

    if (!result.success) {
      throw new ReproducerError(
        'Reproduction output failed schema validation: ' +
          z.prettifyError(result.error),
        ReproducerErrorCode.invalid_output,
        {
          retryable: true,
          cause: result.error
        }
      )
    }

    return result.data
  }

  private async assertFreshWorkspace(
    repositoryTools: RepositoryTools,
    expectedRevision: string
  ): Promise<void> {
    const currentRevision = await repositoryTools.getWorkspaceRevision()

    if (currentRevision !== expectedRevision) {
      throw new ReproducerError(
        'Reproducer context contains a stale workspace revision',
        ReproducerErrorCode.stale_workspace,
        {
          retryable: true
        }
      )
    }
  }

  private async inspectTestStructure(
    input: ReproductionInput,
    promptVersion: PromptVersionIdentifier,
    repositoryTools: RepositoryTools,
    workspaceRevision: string
  ) {
    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: reproducerStep,
      agent: AgentRole.reproducer,
      workspaceRevision,
      type: TraceEventType.tool_call,
      promptVersion,
      input: {
        name: 'inspectTestStructure'
      }
    })

    const result = await this.testStructureInspector.inspect(
      repositoryTools,
      workspaceRevision
    )

    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: reproducerStep,
      agent: AgentRole.reproducer,
      workspaceRevision,
      type: TraceEventType.tool_result,
      promptVersion,
      output: {
        name: 'inspectTestStructure',
        framework: result.framework,
        testScript: result.testScript,
        configFiles: result.configFiles.map((file) => file.path),
        testFiles: result.testFiles.map((file) => file.path)
      }
    })

    return result
  }

  private async applyPatch(
    input: ReproductionInput,
    promptVersion: PromptVersionIdentifier,
    repositoryTools: RepositoryTools,
    plan: ReproductionPlan
  ) {
    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: reproducerStep,
      agent: AgentRole.reproducer,
      workspaceRevision: input.workspace.workspaceRevision,
      type: TraceEventType.tool_call,
      promptVersion,
      input: {
        name: 'applyReproductionPatch',
        testFiles: plan.testFiles
      }
    })

    try {
      const result = await repositoryTools.applyPatch(plan.patch)

      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: reproducerStep,
        agent: AgentRole.reproducer,
        workspaceRevision: result.workspaceRevision,
        type: TraceEventType.tool_result,
        promptVersion,
        output: {
          name: 'applyReproductionPatch',
          changedFiles: result.changedFiles,
          workspaceRevision: result.workspaceRevision
        }
      })

      return result
    } catch (error) {
      throw new ReproducerError(
        'Failed to apply reproduction test patch',
        ReproducerErrorCode.patch_application_failed,
        {
          retryable: true,
          cause: error
        }
      )
    }
  }

  private async runTests(
    input: ReproductionInput,
    promptVersion: PromptVersionIdentifier,
    runTests: () => Promise<ProcessOperationResult>,
    workspaceRevision: string
  ): Promise<ProcessOperationResult> {
    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: reproducerStep,
      agent: AgentRole.reproducer,
      workspaceRevision,
      type: TraceEventType.tool_call,
      promptVersion,
      input: {
        name: 'runTests'
      }
    })

    const result = await runTests()

    await this.traceRecorder.record({
      runId: input.context.context.runId,
      step: reproducerStep,
      agent: AgentRole.reproducer,
      workspaceRevision,
      type: TraceEventType.tool_result,
      promptVersion,
      durationMs: result.durationMs,
      output: {
        name: 'runTests',
        executionId: result.executionId,
        exitCode: result.exitCode,
        signal: result.signal,
        timedOut: result.timedOut,
        succeeded: result.succeeded,
        artifact: result.artifact
      }
    })

    return result
  }

  private recordModelCall(
    input: ReproductionInput,
    promptVersion: PromptVersionIdentifier,
    result: ModelResult<ReproductionPlan>
  ): Promise<void> {
    return this.traceRecorder.record({
      runId: input.context.context.runId,
      step: reproducerStep,
      agent: AgentRole.reproducer,
      workspaceRevision: input.workspace.workspaceRevision,
      type: TraceEventType.agent_call,
      promptVersion,
      durationMs: result.durationMs,
      tokenUsage: result.usage,
      output: {
        returnedStructuredOutput: result.output !== undefined,
        toolCalls: result.toolCalls.map((toolCall) => toolCall.name)
      }
    })
  }

  private async recordFailure(
    input: ReproductionInput,
    promptVersion: PromptVersionIdentifier | undefined,
    error: unknown,
    logger: Logger
  ): Promise<void> {
    try {
      await this.traceRecorder.record({
        runId: input.context.context.runId,
        step: reproducerStep,
        agent: AgentRole.reproducer,
        workspaceRevision: input.context.context.workspaceRevision,
        type: TraceEventType.failure,
        error: toTraceError(error),

        ...(promptVersion === undefined
          ? {}
          : {
              promptVersion
            })
      })
    } catch (traceError) {
      logger.warn('Failed to record reproducer failure', {
        traceError
      })
    }
  }
}

function assertChangedFilesMatch(
  expectedFiles: readonly string[],
  actualFiles: readonly string[]
): void {
  const expected = [...expectedFiles].sort()
  const actual = [...actualFiles].sort()

  if (expected.length !== actual.length) {
    throw new ReproducerError(
      'Applied patch changed unexpected files',
      ReproducerErrorCode.changed_files_mismatch
    )
  }

  for (let index = 0; index < expected.length; index += 1) {
    if (expected[index] !== actual[index]) {
      throw new ReproducerError(
        'Applied patch changed unexpected files',
        ReproducerErrorCode.changed_files_mismatch
      )
    }
  }
}

function toTraceError(error: unknown): {
  name: string
  message: string
  code?: string
  retryable?: boolean
} {
  if (!(error instanceof Error)) {
    return {
      name: 'UnknownError',
      message: 'Unknown reproducer failure'
    }
  }

  const result: {
    name: string
    message: string
    code?: string
    retryable?: boolean
  } = {
    name: error.name,
    message: error.message
  }

  if ('code' in error && typeof error.code === 'string') {
    result.code = error.code
  }

  if ('retryable' in error && typeof error.retryable === 'boolean') {
    result.retryable = error.retryable
  }

  return result
}

