import type { ProcessOperationResult } from '~/core/process'

import { ProcessOperation } from '~/core/process'
import { ReproducerError, ReproducerErrorCode } from '~/core/reproduction'

const unrelatedFailurePatterns: readonly RegExp[] = [
  /\bno test files found\b/i,
  /\bno tests found\b/i,
  /\bcannot find module\b/i,
  /\berr_module_not_found\b/i,
  /\bfailed to resolve import\b/i,
  /\btest suite failed to run\b/i,
  /\bsyntaxerror\b/i,
  /\bts\d{4}:/i,
  /\bmissing script:\s*["']?test/i,
  /\bcommand not found\b/i
]

export class ReproductionGate {
  assertExpectedFailure(
    commandResult: ProcessOperationResult,
    expectedFailureMarker: string
  ): void {
    if (commandResult.operation !== ProcessOperation.run_tests) {
      throw new ReproducerError(
        'Reproduction gate received a non-test command result',
        ReproducerErrorCode.test_execution_failed
      )
    }

    if (commandResult.timedOut) {
      throw new ReproducerError(
        'Reproduction test timed out',
        ReproducerErrorCode.test_execution_failed,
        {
          retryable: true
        }
      )
    }

    if (commandResult.succeeded || commandResult.exitCode === 0) {
      throw new ReproducerError(
        'Reproduction test passed before implementation',
        ReproducerErrorCode.test_already_passes,
        {
          retryable: true
        }
      )
    }

    if (commandResult.exitCode === null) {
      throw new ReproducerError(
        'Reproduction test did not produce an exit code',
        ReproducerErrorCode.test_execution_failed,
        {
          retryable: true
        }
      )
    }

    const output = normalizeOutput(
      `${commandResult.stdout}\n${commandResult.stderr}`
    )

    if (!output.includes(expectedFailureMarker)) {
      throw new ReproducerError(
        'Reproduction test failed for an unrelated reason',
        ReproducerErrorCode.unrelated_test_failure,
        {
          retryable: true
        }
      )
    }

    const unrelatedFailure = unrelatedFailurePatterns.find((pattern) =>
      pattern.test(output)
    )

    if (unrelatedFailure !== undefined) {
      throw new ReproducerError(
        'Reproduction output contains an infrastructure ' +
          'or test setup failure',
        ReproducerErrorCode.unrelated_test_failure,
        {
          retryable: true
        }
      )
    }
  }
}

function normalizeOutput(output: string): string {
  return (
    output
      // eslint-disable-next-line no-control-regex
      .replaceAll(/\u001B\[[0-?]*[ -/]*[@-~]/g, '')
      .replaceAll('\r\n', '\n')
  )
}

import type { ReproductionPlan } from '~/core/reproduction'

import { describe, expect, it } from 'vitest'
import { ReproductionPatchValidator } from '~/application/reproducer'
import { ReproducerErrorCode } from '~/core/reproduction'

const workspaceRevision = 'revision-001'

const marker = 'AGENT_FIX_REPRODUCTION: expected one payment'

describe('ReproductionPatchValidator', () => {
  it('accepts a test-only additive patch', () => {
    const validator = new ReproductionPatchValidator()

    expect(validator.validate(createPlan(), workspaceRevision)).toEqual([
      'tests/payment-webhook.test.ts'
    ])
  })

  it('rejects production file changes', () => {
    const validator = new ReproductionPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          testFiles: ['src/payment-service.ts'],
          patch: [
            'diff --git a/src/payment-service.ts b/src/payment-service.ts',
            'index 1111111..2222222 100644',
            '--- a/src/payment-service.ts',
            '+++ b/src/payment-service.ts',
            '@@ -1,1 +1,2 @@',
            ' export const value = 1',
            '+export const changed = true'
          ].join('\n')
        }),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ReproducerErrorCode.forbidden_file_change
      })
    )
  })

  it('rejects removal of existing test code', () => {
    const validator = new ReproductionPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          patch: [
            'diff --git a/tests/payment-webhook.test.ts b/tests/payment-webhook.test.ts',
            'index 1111111..2222222 100644',
            '--- a/tests/payment-webhook.test.ts',
            '+++ b/tests/payment-webhook.test.ts',
            '@@ -1,2 +1,2 @@',
            '-it("old test", () => {})',
            `+throw new Error('${marker}')`
          ].join('\n')
        }),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ReproducerErrorCode.invalid_patch
      })
    )
  })

  it('rejects a stale patch plan', () => {
    const validator = new ReproductionPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          workspaceRevision: 'revision-old'
        }),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ReproducerErrorCode.stale_workspace
      })
    )
  })

  it('requires the expected failure marker in added code', () => {
    const validator = new ReproductionPatchValidator()

    expect(() =>
      validator.validate(
        createPlan({
          patch: [
            'diff --git a/tests/payment-webhook.test.ts b/tests/payment-webhook.test.ts',
            'index 1111111..2222222 100644',
            '--- a/tests/payment-webhook.test.ts',
            '+++ b/tests/payment-webhook.test.ts',
            '@@ -1,1 +1,2 @@',
            ' describe("webhook", () => {})',
            '+throw new Error("different marker")'
          ].join('\n')
        }),
        workspaceRevision
      )
    ).toThrowError(
      expect.objectContaining({
        code: ReproducerErrorCode.invalid_patch
      })
    )
  })
})

function createPlan(
  overrides: Partial<ReproductionPlan> = {}
): ReproductionPlan {
  return {
    summary: 'Add a regression test for duplicate webhook delivery',

    testFiles: ['tests/payment-webhook.test.ts'],

    expectedFailureMarker: marker,

    workspaceRevision,

    patch: [
      'diff --git a/tests/payment-webhook.test.ts b/tests/payment-webhook.test.ts',
      'index 1111111..2222222 100644',
      '--- a/tests/payment-webhook.test.ts',
      '+++ b/tests/payment-webhook.test.ts',
      '@@ -1,1 +1,6 @@',
      ' describe("webhook", () => {})',
      '+',
      '+if (payments.length !== 1) {',
      `+  throw new Error('${marker}')`,
      '+}'
    ].join('\n'),

    ...overrides
  }
}

import type { ReproductionPlan } from '~/core/reproduction'

import {
  ReproducerError,
  ReproducerErrorCode,
  isTestFilePath
} from '~/core/reproduction'

const diffHeaderPattern = /^diff --git a\/(.+) b\/(.+)$/gm

const forbiddenPatchMarkers = [
  'GIT binary patch',
  'Binary files ',
  'rename from ',
  'rename to ',
  'deleted file mode '
]

export class ReproductionPatchValidator {
  validate(
    plan: ReproductionPlan,
    expectedWorkspaceRevision: string
  ): readonly string[] {
    if (plan.workspaceRevision !== expectedWorkspaceRevision) {
      throw new ReproducerError(
        'Reproduction patch was produced from a stale workspace',
        ReproducerErrorCode.stale_workspace,
        {
          retryable: true
        }
      )
    }

    for (const marker of forbiddenPatchMarkers) {
      if (plan.patch.includes(marker)) {
        throw new ReproducerError(
          `Reproduction patch contains forbidden marker: ${marker}`,
          ReproducerErrorCode.invalid_patch,
          {
            retryable: true
          }
        )
      }
    }

    const changedFiles = extractChangedFiles(plan.patch)

    if (changedFiles.length === 0) {
      throw new ReproducerError(
        'Reproduction patch does not contain changed files',
        ReproducerErrorCode.invalid_patch,
        {
          retryable: true
        }
      )
    }

    for (const filePath of changedFiles) {
      if (!isSafeRelativePath(filePath)) {
        throw new ReproducerError(
          `Reproduction patch contains unsafe path: ${filePath}`,
          ReproducerErrorCode.invalid_patch
        )
      }

      if (!isTestFilePath(filePath)) {
        throw new ReproducerError(
          `Reproducer attempted to modify non-test file: ${filePath}`,
          ReproducerErrorCode.forbidden_file_change
        )
      }
    }

    assertOnlyAdditions(plan.patch)

    assertSameFiles(changedFiles, plan.testFiles)

    const addedContent = extractAddedContent(plan.patch)

    if (!addedContent.includes(plan.expectedFailureMarker)) {
      throw new ReproducerError(
        'Reproduction patch does not contain the ' +
          'expected failure marker',
        ReproducerErrorCode.invalid_patch,
        {
          retryable: true
        }
      )
    }

    return changedFiles
  }
}

function extractChangedFiles(patch: string): string[] {
  const files: string[] = []
  let match: RegExpExecArray | null

  diffHeaderPattern.lastIndex = 0

  while ((match = diffHeaderPattern.exec(patch)) !== null) {
    const sourcePath = match[1]
    const targetPath = match[2]

    if (
      sourcePath === undefined ||
      targetPath === undefined ||
      sourcePath !== targetPath
    ) {
      throw new ReproducerError(
        'Reproduction patch contains a rename or invalid diff header',
        ReproducerErrorCode.invalid_patch
      )
    }

    if (!files.includes(targetPath)) {
      files.push(targetPath)
    }
  }

  return files
}

function assertOnlyAdditions(patch: string): void {
  const lines = patch.split(/\r?\n/)

  let additionCount = 0

  for (const line of lines) {
    if (line.startsWith('--- ') || line.startsWith('+++ ')) {
      continue
    }

    if (line.startsWith('-')) {
      throw new ReproducerError(
        'Reproduction patch may only add test code',
        ReproducerErrorCode.invalid_patch,
        {
          retryable: true
        }
      )
    }

    if (line.startsWith('+')) {
      additionCount += 1
    }
  }

  if (additionCount === 0) {
    throw new ReproducerError(
      'Reproduction patch does not add test code',
      ReproducerErrorCode.invalid_patch,
      {
        retryable: true
      }
    )
  }
}

function extractAddedContent(patch: string): string {
  return patch
    .split(/\r?\n/)
    .filter((line) => line.startsWith('+') && !line.startsWith('+++ '))
    .map((line) => line.slice(1))
    .join('\n')
}

function assertSameFiles(
  patchFiles: readonly string[],
  declaredFiles: readonly string[]
): void {
  const normalizedPatchFiles = [...patchFiles].sort()

  const normalizedDeclaredFiles = [...declaredFiles].sort()

  if (normalizedPatchFiles.length !== normalizedDeclaredFiles.length) {
    throw new ReproducerError(
      'Declared test files do not match patch files',
      ReproducerErrorCode.invalid_patch,
      {
        retryable: true
      }
    )
  }

  for (let index = 0; index < normalizedPatchFiles.length; index += 1) {
    if (normalizedPatchFiles[index] !== normalizedDeclaredFiles[index]) {
      throw new ReproducerError(
        'Declared test files do not match patch files',
        ReproducerErrorCode.invalid_patch,
        {
          retryable: true
        }
      )
    }
  }
}

function isSafeRelativePath(filePath: string): boolean {
  if (
    filePath.startsWith('/') ||
    filePath.startsWith('\\') ||
    filePath.includes('\\') ||
    /^[a-zA-Z]:/.test(filePath)
  ) {
    return false
  }

  return filePath
    .split('/')
    .every(
      (segment) =>
        segment.length > 0 && segment !== '.' && segment !== '..'
    )
}

import type {
  TestSourceFile,
  TestStructureSnapshot
} from '~/core/reproduction'
import type { RepositoryFile, RepositoryTools } from '~/core/workspace'

const defaultMaximumTestFiles = 12
const defaultMaximumContentLength = 80_000

export interface TestStructureInspectorOptions {
  readonly maximumTestFiles?: number
  readonly maximumContentLength?: number
}

export class TestStructureInspector {
  private readonly maximumTestFiles: number
  private readonly maximumContentLength: number

  constructor(options: TestStructureInspectorOptions = {}) {
    this.maximumTestFiles =
      options.maximumTestFiles ?? defaultMaximumTestFiles

    this.maximumContentLength =
      options.maximumContentLength ?? defaultMaximumContentLength
  }

  async inspect(
    repositoryTools: RepositoryTools,
    workspaceRevision: string
  ): Promise<TestStructureSnapshot> {
    const repositoryFiles = await repositoryTools.listFiles()

    const packageFile = repositoryFiles.find(
      (file) => file.path === 'package.json'
    )

    const configFiles = repositoryFiles
      .filter(isTestConfigFile)
      .sort(compareRepositoryFiles)

    const testFiles = repositoryFiles
      .filter(isTestSourceFile)
      .sort(compareRepositoryFiles)
      .slice(0, this.maximumTestFiles)

    let remainingContentLength = this.maximumContentLength

    const loadedConfigFiles: TestSourceFile[] = []
    const loadedTestFiles: TestSourceFile[] = []

    let packageContent: string | null = null

    if (packageFile !== undefined) {
      const loadedPackage = await this.readBoundedFile(
        packageFile,
        repositoryTools,
        remainingContentLength
      )

      loadedConfigFiles.push(loadedPackage.file)

      remainingContentLength -= loadedPackage.consumedLength

      packageContent = loadedPackage.file.content
    }

    for (const file of configFiles) {
      if (file.path === 'package.json' || remainingContentLength <= 0) {
        continue
      }

      const loaded = await this.readBoundedFile(
        file,
        repositoryTools,
        remainingContentLength
      )

      loadedConfigFiles.push(loaded.file)

      remainingContentLength -= loaded.consumedLength
    }

    for (const file of testFiles) {
      if (remainingContentLength <= 0) {
        break
      }

      const loaded = await this.readBoundedFile(
        file,
        repositoryTools,
        remainingContentLength
      )

      loadedTestFiles.push(loaded.file)

      remainingContentLength -= loaded.consumedLength
    }

    const packageMetadata = parsePackageMetadata(packageContent)

    return {
      framework: packageMetadata.framework,
      testScript: packageMetadata.testScript,
      configFiles: loadedConfigFiles,
      testFiles: loadedTestFiles,
      workspaceRevision
    }
  }

  private async readBoundedFile(
    file: RepositoryFile,
    repositoryTools: RepositoryTools,
    maximumLength: number
  ): Promise<{
    readonly file: TestSourceFile
    readonly consumedLength: number
  }> {
    const result = await repositoryTools.readFile(file.path)

    const content = result.content.slice(0, maximumLength)

    return {
      file: {
        path: result.path,
        content,
        truncated: content.length < result.content.length
      },
      consumedLength: content.length
    }
  }
}

interface PackageMetadata {
  readonly framework: string | null
  readonly testScript: string | null
}

function parsePackageMetadata(content: string | null): PackageMetadata {
  if (content === null) {
    return {
      framework: null,
      testScript: null
    }
  }

  try {
    const parsed: unknown = JSON.parse(content)
    const packageRecord = toRecord(parsed)

    if (packageRecord === null) {
      return {
        framework: null,
        testScript: null
      }
    }

    const scripts = toStringRecord(packageRecord.scripts)

    const dependencies = {
      ...toStringRecord(packageRecord.dependencies),
      ...toStringRecord(packageRecord.devDependencies)
    }

    return {
      framework: detectTestFramework(dependencies, scripts.test),
      testScript: scripts.test ?? null
    }
  } catch {
    return {
      framework: null,
      testScript: null
    }
  }
}

function detectTestFramework(
  dependencies: Readonly<Record<string, string>>,
  testScript: string | undefined
): string | null {
  if ('vitest' in dependencies) {
    return 'vitest'
  }

  if ('jest' in dependencies) {
    return 'jest'
  }

  if ('mocha' in dependencies) {
    return 'mocha'
  }

  if ('@playwright/test' in dependencies) {
    return 'playwright'
  }

  if (testScript !== undefined && testScript.includes('node --test')) {
    return 'node:test'
  }

  return null
}

function toRecord(value: unknown): Record<string, unknown> | null {
  if (
    typeof value !== 'object' ||
    value === null ||
    Array.isArray(value)
  ) {
    return null
  }

  return value as Record<string, unknown>
}

function toStringRecord(value: unknown): Record<string, string> {
  const record = toRecord(value)

  if (record === null) {
    return {}
  }

  const result: Record<string, string> = {}

  for (const [key, nestedValue] of Object.entries(record)) {
    if (typeof nestedValue === 'string') {
      result[key] = nestedValue
    }
  }

  return result
}

function isTestConfigFile(file: RepositoryFile): boolean {
  return (
    file.path === 'package.json' ||
    /(^|\/)(vitest|jest|playwright)\.config\.[cm]?[jt]s$/.test(
      file.path
    ) ||
    /(^|\/)tsconfig(?:\.[a-zA-Z0-9_-]+)?\.json$/.test(file.path)
  )
}

function isTestSourceFile(file: RepositoryFile): boolean {
  const normalizedPath = file.path.toLowerCase()
  const fileName = normalizedPath.split('/').at(-1) ?? ''

  const testDirectory =
    normalizedPath.startsWith('test/') ||
    normalizedPath.startsWith('tests/') ||
    normalizedPath.includes('/test/') ||
    normalizedPath.includes('/tests/') ||
    normalizedPath.includes('/__tests__/')

  const testFileName =
    fileName.includes('.test.') || fileName.includes('.spec.')

  return (
    /\.(?:[cm]?[jt]sx?)$/.test(fileName) && (testDirectory || testFileName)
  )
}

function compareRepositoryFiles(
  left: RepositoryFile,
  right: RepositoryFile
): number {
  return left.path.localeCompare(right.path)
}

