  }
}

describe('RunCommandHandler', () => {
  it('creates a run, validates the repository and saves approval', async () => {
    const temporaryRoot = await mkdtemp(
      path.join(tmpdir(), 'agent-fix-run-')
    )

    try {
      const repositoryPath = path.join(temporaryRoot, 'repository')

      const runsRoot = path.join(temporaryRoot, 'runs')

      await mkdir(repositoryPath, {
        recursive: true
      })

      await runGit(['init'], repositoryPath)

      await writeFile(
        path.join(repositoryPath, 'README.md'),
        '# fixture\n',
        'utf8'
      )

      await runGit(['add', '.'], repositoryPath)

      await runGit(
        [
          '-c',
          'user.name=AgentFix Test',
          '-c',
          'user.email=agent-fix@example.test',
          'commit',
          '-m',
          'initial'
        ],
        repositoryPath
      )

      const runStore = new FileRunStore(runsRoot)

      const runService = new RunService(
        runStore,
        () => new Date('2026-08-03T19:00:00.000Z'),
        () => 'run-001'
      )

      const traceRecorder = new TraceRecorder(
        new JsonlTraceWriter({
          runsRoot
        }),
        () => new Date('2026-08-03T19:00:00.000Z')
      )

      const output = new MemoryOutput()

      const workspaceManager = new GitWorkspaceManager({
        runsRoot
      })

      const handler = new RunCommandHandler(
        runService,
        new GitTargetRepositoryValidator(),
        workspaceManager,
        new ApprovedPrompt(),
        output,
        createPinoLogger({
          level: LogLevel.silent,
          pretty: false
        }),
        traceRecorder
      )

      const exitCode = await handler.execute({
        repositoryPath,
        task: 'Duplicate webhook creates two payments'
      })

      await traceRecorder.flush()

      expect(exitCode).toBe(0)
      expect(output.errors).toEqual([])

      const runDirectory = path.join(runsRoot, 'run-001')

      const state = JSON.parse(
        await readFile(path.join(runDirectory, 'state.json'), 'utf8')
      ) as Record<string, unknown>

      const validation = JSON.parse(
        await readFile(path.join(runDirectory, 'validation.json'), 'utf8')
      ) as Record<string, unknown>

      const events = await readFile(
        path.join(runDirectory, 'events.jsonl'),
        'utf8'
      )

      expect(state).toMatchObject({
        runId: 'run-001',
        status: RunStatus.approved,
        currentStep: null,
        repositoryRoot: repositoryPath,
        workspacePath: path.join(runsRoot, 'run-001', 'workspace'),
        approval: {
          decision: HumanApprovalDecision.approved
        }
      })

      expect(state.baseCommit).toMatch(/^[a-f0-9]{40}$/)

      expect(state.workspaceRevision).toMatch(/^sha256:/)

      expect(validation).toMatchObject({
        passed: true,
        repositoryPath
      })

      expect(events).toContain('"type":"validation.result"')

      expect(events).toContain('"step":"prepare_workspace"')
    } finally {
      await rm(temporaryRoot, {
        recursive: true,
        force: true
      })
    }
  })
})

function runGit(args: readonly string[], cwd: string): Promise<void> {
  return new Promise((resolve, reject) => {
    execFile(
      'git',
      [...args],
      {
        cwd
      },
      (error) => {
        if (error !== null) {
          reject(error)
          return
        }

        resolve()
      }
    )
  })
}

import type { RunService } from '~/application/run/run-service'
import type { CliOutput } from '~/core/cli'
import type { Logger } from '~/core/logging'
import type {
  HumanApprovalPrompt,
  RunState,
  RunValidationReport,
  TargetRepositoryValidator
} from '~/core/run'
import type { TraceRecorder } from '~/core/trace'
import type { WorkspaceManager } from '~/core/workspace'

import { HumanApprovalDecision, RunStatus, RunStepName } from '~/core/run'
import { TraceEventType } from '~/core/trace'

export interface RunCommandInput {
  readonly repositoryPath: string
  readonly task: string
}

export class RunCommandHandler {
  constructor(
    private readonly runService: RunService,
    private readonly repositoryValidator: TargetRepositoryValidator,
    private readonly workspaceManager: WorkspaceManager,
    private readonly approvalPrompt: HumanApprovalPrompt,
    private readonly output: CliOutput,
    private readonly logger: Logger,
    private readonly traceRecorder: TraceRecorder
  ) {}

  async execute(input: RunCommandInput): Promise<number> {
    let state = await this.runService.create(input)

    const logger = this.logger.child({
      runId: state.runId,
      step: 'run-command'
    })

    this.output.writeLine(`Run created: ${state.runId}`)
    this.output.writeLine(`Run directory: ${state.runDirectory}`)

    try {
      state = await this.runService.startStep(
        state,
        RunStepName.validate_target,
        RunStatus.validating
      )

      this.printProgress(state, 'Validating target repository')

      const validation = await this.repositoryValidator.validate(
        state.repositoryPath
      )

      await this.runService.saveValidation(state, validation)

      await this.traceRecorder.record({
        runId: state.runId,
        step: RunStepName.validate_target,
        type: TraceEventType.validation_result,
        output: validation
      })

      this.printValidation(validation)

      if (!validation.passed) {
        const validationError = new Error(
          'Target repository validation failed'
        )

        state = await this.runService.failStep(state, validationError)

        await this.traceRecorder.record({
          runId: state.runId,
          step: RunStepName.validate_target,
          type: TraceEventType.failure,
          error: {
            name: validationError.name,
            message: validationError.message
          }
        })

        logger.warn('Target repository validation failed', {
          repositoryPath: state.repositoryPath
        })

        this.output.writeError('Run stopped: target repository is invalid')

        return 1
      }

      state = await this.runService.completeStep(
        state,
        RunStepName.validate_target,
        RunStatus.ready,
        'Target repository validation passed'
      )

      state = await this.runService.startStep(
        state,
        RunStepName.prepare_workspace,
        RunStatus.preparing_workspace
      )

      this.printProgress(state, 'Creating isolated Git workspace')

      const workspace = await this.workspaceManager.create({
        runId: state.runId,
        repositoryPath: state.repositoryPath
      })

      state = await this.runService.attachWorkspace(state, workspace)

      await this.traceRecorder.record({
        runId: state.runId,
        step: RunStepName.prepare_workspace,
        workspaceRevision: workspace.workspaceRevision,
        type: TraceEventType.tool_result,
        output: {
          workspacePath: workspace.workspacePath,
          baseCommit: workspace.baseCommit,
          workspaceRevision: workspace.workspaceRevision
        }
      })

      this.output.writeLine(`Workspace: ${workspace.workspacePath}`)

      this.output.writeLine(`Base commit: ${workspace.baseCommit}`)

      this.output.writeLine(
        `Workspace revision: ${workspace.workspaceRevision}`
      )

      state = await this.runService.startStep(
        state,
        RunStepName.human_approval,
        RunStatus.awaiting_approval
      )

      this.printProgress(state, 'Waiting for human approval')

      const decision = await this.approvalPrompt.requestApproval({
        runId: state.runId,
        repositoryPath: state.repositoryPath,
        task: state.task,
        validation
      })

      state = await this.runService.recordApproval(state, decision)

      if (decision === HumanApprovalDecision.approved) {
        logger.info('Run approved by human')

        this.output.writeLine(`Run ${state.runId} approved`)
      } else {
        logger.info('Run rejected by human')

        this.output.writeLine(`Run ${state.runId} rejected`)
      }

      return 0
    } catch (error) {
      const failedStep = state.currentStep ?? 'run-command'

      if (state.currentStep !== null) {
        state = await this.runService.failStep(state, error)
      }

      await this.traceRecorder.record({
        runId: state.runId,
        step: failedStep,
        type: TraceEventType.failure,
        error: toTraceError(error),
        ...(state.workspaceRevision === null
          ? {}
          : {
              workspaceRevision: state.workspaceRevision
            })
      })

      logger.error('Run command failed', {
        error
      })

      throw error
    }
  }

  private printProgress(state: RunState, message: string): void {
    this.output.writeLine(
      `[${state.runId}] ${state.currentStep ?? 'unknown'}: ${message}`
    )
  }

  private printValidation(report: RunValidationReport): void {
    this.output.writeLine('')
    this.output.writeLine('Validation results:')

    for (const check of report.checks) {
      const marker = check.passed ? 'PASS' : 'FAIL'

      this.output.writeLine(`  [${marker}] ${check.message}`)
    }

    this.output.writeLine(
      `Validation: ${report.passed ? 'PASSED' : 'FAILED'}`
    )

    this.output.writeLine('')
  }
}

function toTraceError(error: unknown): {
  name: string
  message: string
  code?: string
  retryable?: boolean
} {
  if (!(error instanceof Error)) {
    return {
      name: 'UnknownError',
      message: 'Unknown run command failure'
    }
  }

  const result: {
    name: string
    message: string
    code?: string
    retryable?: boolean
  } = {
    name: error.name,
    message: error.message
  }

  if ('code' in error && typeof error.code === 'string') {
    result.code = error.code
  }

  if ('retryable' in error && typeof error.retryable === 'boolean') {
    result.retryable = error.retryable
  }

  return result
}

import type { RunState, RunStore, RunValidationReport } from '~/core/run'
import type { WorkspaceSnapshot } from '~/core/workspace'

import { randomUUID } from 'node:crypto'
import {
  HumanApprovalDecision,
  RunStatus,
  RunStepName,
  RunStepStatus
} from '~/core/run'

export interface CreateRunInput {
  readonly repositoryPath: string
  readonly task: string
}

export type RunIdFactory = (now: Date) => string

export class RunService {
  constructor(
    private readonly store: RunStore,
    private readonly now: () => Date = () => new Date(),
    private readonly runIdFactory: RunIdFactory = createRunId
  ) {}

  async create(input: CreateRunInput): Promise<RunState> {
    const now = this.now()
    const timestamp = now.toISOString()
    const runId = this.runIdFactory(now)

    const state: RunState = {
      schemaVersion: 1,
      runId,
      repositoryPath: input.repositoryPath,
      task: input.task,
      runDirectory: this.store.getRunDirectory(runId),
      status: RunStatus.created,
      currentStep: null,
      createdAt: timestamp,
      updatedAt: timestamp,
      approval: null,
      failure: null,
      repositoryRoot: null,
      repositoryRelativePath: null,
      workspaceRoot: null,
      workspacePath: null,
      baseCommit: null,
      workspaceRevision: null,
      steps: [
        {
          name: RunStepName.initialize_run,
          status: RunStepStatus.succeeded,
          startedAt: timestamp,
          completedAt: timestamp,
          message: 'Run directory initialized'
        }
      ]
    }

    await this.store.create({
      state
    })

    return state
  }

  async startStep(
    state: RunState,
    stepName: RunStepName,
    status: RunStatus
  ): Promise<RunState> {
    if (state.currentStep !== null) {
      throw new Error(
        `Run ${state.runId} already has active step ${state.currentStep}`
      )
    }

    const timestamp = this.now().toISOString()

    const nextState: RunState = {
      ...state,
      status,
      currentStep: stepName,
      updatedAt: timestamp,
      steps: [
        ...state.steps,
        {
          name: stepName,
          status: RunStepStatus.running,
          startedAt: timestamp,
          completedAt: null,
          message: null
        }
      ]
    }

    await this.store.saveState(nextState)

    return nextState
  }

  async completeStep(
    state: RunState,
    stepName: RunStepName,
    status: RunStatus,
    message: string
  ): Promise<RunState> {
    this.assertCurrentStep(state, stepName)

    const timestamp = this.now().toISOString()
    const stepIndex = this.findCurrentStepIndex(state, stepName)

    const steps = state.steps.map((step, index) =>
      index === stepIndex
        ? {
            ...step,
            status: RunStepStatus.succeeded,
            completedAt: timestamp,
            message
          }
        : step
    )

    const nextState: RunState = {
      ...state,
      status,
      currentStep: null,
      updatedAt: timestamp,
      steps
    }

    await this.store.saveState(nextState)

    return nextState
  }

  async failStep(state: RunState, error: unknown): Promise<RunState> {
    if (state.currentStep === null) {
      throw new Error(`Run ${state.runId} does not have an active step`)
    }

    const timestamp = this.now().toISOString()
    const message = getErrorMessage(error)
    const code = getErrorCode(error)

    const stepIndex = this.findCurrentStepIndex(state, state.currentStep)

    const steps = state.steps.map((step, index) =>
      index === stepIndex
        ? {
            ...step,
            status: RunStepStatus.failed,
            completedAt: timestamp,
            message
          }
        : step
    )

    const nextState: RunState = {
      ...state,
      status: RunStatus.failed,
      currentStep: null,
      updatedAt: timestamp,
      steps,
      failure: {
        message,
        code,
        failedAt: timestamp
      }
    }

    await this.store.saveState(nextState)

    return nextState
  }

  async recordApproval(
    state: RunState,
    decision: HumanApprovalDecision
  ): Promise<RunState> {
    this.assertCurrentStep(state, RunStepName.human_approval)

    const timestamp = this.now().toISOString()
    const stepIndex = this.findCurrentStepIndex(
      state,
      RunStepName.human_approval
    )

    const approved = decision === HumanApprovalDecision.approved

    const steps = state.steps.map((step, index) =>
      index === stepIndex
        ? {
            ...step,
            status: approved
              ? RunStepStatus.succeeded
              : RunStepStatus.rejected,
            completedAt: timestamp,
            message: approved
              ? 'Run approved by human'
              : 'Run rejected by human'
          }
        : step
    )

    const nextState: RunState = {
      ...state,
      status: approved ? RunStatus.approved : RunStatus.rejected,
      currentStep: null,
      updatedAt: timestamp,
      steps,
      approval: {
        decision,
        decidedAt: timestamp
      }
    }

    await this.store.saveState(nextState)

    return nextState
  }

  saveValidation(
    state: RunState,
    report: RunValidationReport
  ): Promise<void> {
    return this.store.saveValidation(state.runId, report)
  }

  async attachWorkspace(
    state: RunState,
    workspace: WorkspaceSnapshot
  ): Promise<RunState> {
    this.assertCurrentStep(state, RunStepName.prepare_workspace)

    const timestamp = this.now().toISOString()

    const stepIndex = this.findCurrentStepIndex(
      state,
      RunStepName.prepare_workspace
    )

    const steps = state.steps.map((step, index) =>
      index === stepIndex
        ? {
            ...step,
            status: RunStepStatus.succeeded,
            completedAt: timestamp,
            message: 'Isolated Git workspace created'
          }
        : step
    )

    const nextState: RunState = {
      ...state,
      repositoryPath: workspace.repositoryPath,
      repositoryRoot: workspace.repositoryRoot,
      repositoryRelativePath: workspace.repositoryRelativePath,
      workspaceRoot: workspace.workspaceRoot,
      workspacePath: workspace.workspacePath,
      baseCommit: workspace.baseCommit,
      workspaceRevision: workspace.workspaceRevision,
      status: RunStatus.ready,
      currentStep: null,
      updatedAt: timestamp,
      steps
    }

    await this.store.saveState(nextState)

    return nextState
  }

  private assertCurrentStep(state: RunState, stepName: RunStepName): void {
    if (state.currentStep !== stepName) {
      throw new Error(
        `Expected current step ${stepName}, received ${state.currentStep ?? 'none'}`
      )
    }
  }

  private findCurrentStepIndex(
    state: RunState,
    stepName: RunStepName
  ): number {
    const stepIndex = state.steps.findLastIndex(
      (step) =>
        step.name === stepName && step.status === RunStepStatus.running
    )

    if (stepIndex === -1) {
      throw new Error(`Active step ${stepName} was not found in run state`)
    }

    return stepIndex
  }
}

export function createRunId(now: Date): string {
  const timestamp = now
    .toISOString()
    .replaceAll(/[^0-9]/g, '')
    .slice(0, 14)

  const suffix = randomUUID().slice(0, 8)

  return `run-${timestamp}-${suffix}`
}

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : 'Unknown run failure'
}

function getErrorCode(error: unknown): string | null {
  if (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    typeof error.code === 'string'
  ) {
    return error.code
  }

  return null
}

import type { ImplementationResult } from '~/core/implementation'
