export enum ExecutionFailureKind {
  retryable = 'retryable',
  non_retryable = 'non_retryable',
  fatal = 'fatal'
}

export enum ExecutionErrorCode {
  attempts_exhausted = 'attempts_exhausted',
  checkpoint_corrupted = 'checkpoint_corrupted',
  checkpoint_input_mismatch = 'checkpoint_input_mismatch',
  duplicate_patch_application = 'duplicate_patch_application',
  invalid_attempt_limit = 'invalid_attempt_limit',
  retry_failed = 'retry_failed',
  rollback_failed = 'rollback_failed',
  stale_checkpoint = 'stale_checkpoint'
}

export interface ExecutionErrorOptions {
  readonly kind?: ExecutionFailureKind
  readonly retryable?: boolean
  readonly cause?: unknown
}

export class ExecutionError extends Error {
  readonly code: ExecutionErrorCode
  readonly kind: ExecutionFailureKind
  readonly retryable: boolean
  readonly fatal: boolean

  constructor(
    message: string,
    code: ExecutionErrorCode,
    options: ExecutionErrorOptions = {}
  ) {
    super(message, {
      cause: options.cause
    })

    const kind =
      options.kind ??
      (options.retryable === true
        ? ExecutionFailureKind.retryable
        : ExecutionFailureKind.non_retryable)

    this.name = 'ExecutionError'
    this.code = code
    this.kind = kind
    this.retryable = kind === ExecutionFailureKind.retryable
    this.fatal = kind === ExecutionFailureKind.fatal
  }
}

export class AttemptsExhaustedError extends ExecutionError {
  readonly attempts: number
  readonly lastError: unknown

  constructor(attempts: number, lastError: unknown) {
    super(
      `Maximum attempt limit reached after ${attempts} attempts`,
      ExecutionErrorCode.attempts_exhausted,
      {
        kind: ExecutionFailureKind.non_retryable,
        cause: lastError
      }
    )

    this.name = 'AttemptsExhaustedError'
    this.attempts = attempts
    this.lastError = lastError
  }
}

export function getExecutionFailureKind(
  error: unknown
): ExecutionFailureKind {
  if (isBooleanProperty(error, 'fatal', true)) {
    return ExecutionFailureKind.fatal
  }

  if (isBooleanProperty(error, 'retryable', true)) {
    return ExecutionFailureKind.retryable
  }

  return ExecutionFailureKind.non_retryable
}

export function isRetryableError(error: unknown): boolean {
  return getExecutionFailureKind(error) === ExecutionFailureKind.retryable
}

function isBooleanProperty(
  value: unknown,
  property: string,
  expected: boolean
): boolean {
  return (
    typeof value === 'object' &&
    value !== null &&
    property in value &&
    value[property as keyof typeof value] === expected
  )
}

import type {
  AgentContextSnapshot,
  EvidenceReference
} from '~/core/context'
import type {
  ProcessOperationResult,
  ProcessResultArtifact
} from '~/core/process'
import type { WorkspaceSnapshot } from '~/core/workspace'

import { z } from 'zod'
import { AgentRole } from '~/core/context'

const repositoryRelativePathSchema = z
  .string()
  .trim()
  .min(1)
  .max(500)
  .refine(isRepositoryRelativePath, {
    message: 'Path must be repository-relative'
  })

const confirmedEvidenceSchema = z
  .object({
    id: z.string().trim().min(1).max(200),

    artifactId: z.string().trim().min(1).max(200),

    filePath: repositoryRelativePathSchema,

    claim: z.string().trim().min(1).max(2000),

    confirmed: z.literal(true),

    workspaceRevision: z.string().trim().min(1),

    symbol: z.string().trim().min(1).max(200),

    lineStart: z.number().int().positive(),

    lineEnd: z.number().int().positive()
  })
  .strict()
  .superRefine((evidence, context) => {
    if (evidence.lineEnd < evidence.lineStart) {
      context.addIssue({
        code: 'custom',
        path: ['lineEnd'],
        message: 'lineEnd must be greater than or equal to lineStart'
      })
    }
  })

export const allowedFileScopeSchema = z
  .object({
    files: z.array(repositoryRelativePathSchema).min(1).max(100),

    workspaceRevision: z.string().trim().min(1)
  })
  .strict()
  .superRefine((scope, context) => {
    const uniqueFiles = new Set(scope.files)

    if (uniqueFiles.size !== scope.files.length) {
      context.addIssue({
        code: 'custom',
        path: ['files'],
        message: 'Allowed file scope contains duplicate paths'
      })
    }
  })

const failingCommandResultSchema = z
  .object({
    executionId: z.string().trim().min(1),

    exitCode: z
      .number()
      .int()
      .refine((value) => value !== 0, {
        message:
          'Failing reproduction command must have a non-zero exit code'
      }),

    timedOut: z.literal(false),

    succeeded: z.literal(false),

    stdout: z.string().max(500_000),

    stderr: z.string().max(500_000)
  })
  .strict()

export const reproductionFailureSnapshotSchema = z
  .object({
    testFiles: z.array(repositoryRelativePathSchema).min(1).max(20),

    expectedFailureMarker: z.string().trim().min(1).max(400),

    workspaceRevision: z.string().trim().min(1),

    commandResult: failingCommandResultSchema
  })
  .strict()
  .superRefine((reproduction, context) => {
    const commandOutput =
      `${reproduction.commandResult.stdout}\n` +
      reproduction.commandResult.stderr

    if (!commandOutput.includes(reproduction.expectedFailureMarker)) {
      context.addIssue({
        code: 'custom',
        path: ['commandResult'],
        message:
          'Failing command output does not contain the expected marker'
      })
    }

    const uniqueTestFiles = new Set(reproduction.testFiles)

    if (uniqueTestFiles.size !== reproduction.testFiles.length) {
      context.addIssue({
        code: 'custom',
        path: ['testFiles'],
        message: 'Reproduction snapshot contains duplicate test files'
      })
    }
  })

const implementerContextSnapshotSchema = z
  .object({
    agent: z.literal(AgentRole.implementer),

    createdAt: z.string().trim().min(1),

    estimatedTokens: z.number().int().nonnegative(),

    context: z
      .object({
        runId: z.string().trim().min(1),

        task: z.string().trim().min(1),

        workspaceRevision: z.string().trim().min(1),

