import type { Readable, Writable } from 'node:stream'
import type { HumanApprovalPrompt, HumanApprovalRequest } from '~/core/run'

import { createInterface } from 'node:readline/promises'
import { HumanApprovalDecision } from '~/core/run'

export class ReadlineApprovalPrompt implements HumanApprovalPrompt {
  constructor(
    private readonly input: Readable = process.stdin,
    private readonly output: Writable = process.stdout
  ) {}

  async requestApproval(
    request: HumanApprovalRequest
  ): Promise<HumanApprovalDecision> {
    this.output.write('\nHuman approval required\n')
    this.output.write(`Run: ${request.runId}\n`)
    this.output.write(`Repository: ${request.repositoryPath}\n`)
    this.output.write(`Task: ${request.task}\n`)
    this.output.write(
      `Validation: ${request.validation.passed ? 'PASSED' : 'FAILED'}\n\n`
    )

    const readline = createInterface({
      input: this.input,
      output: this.output
    })

    try {
      while (true) {
        const answer = await readline.question('Approve this run? [y/n]: ')

        const decision = parseApprovalDecision(answer)

        if (decision !== null) {
          return decision
        }

        this.output.write('Enter y/yes or n/no.\n')
      }
    } finally {
      readline.close()
    }
  }
}

export function parseApprovalDecision(
  value: string
): HumanApprovalDecision | null {
  const normalized = value.trim().toLowerCase()

  if (normalized === 'y' || normalized === 'yes') {
    return HumanApprovalDecision.approved
  }

  if (normalized === 'n' || normalized === 'no') {
    return HumanApprovalDecision.rejected
  }

  return null
}

import type {
  RunValidationCheck,
  RunValidationReport,
  TargetRepositoryValidator
} from '~/core/run'

import { access, stat } from 'node:fs/promises'
import path from 'node:path'
import { GitCommandRunner } from '~/infra/git'

export class GitTargetRepositoryValidator implements TargetRepositoryValidator {
  constructor(
    private readonly git = new GitCommandRunner(),
    private readonly now: () => Date = () => new Date()
  ) {}

  async validate(repositoryPath: string): Promise<RunValidationReport> {
    const resolvedPath = path.resolve(repositoryPath)

    const checks: RunValidationCheck[] = []

    const targetStat = await stat(resolvedPath).catch(() => null)

    const exists = targetStat !== null
    const isDirectory = targetStat?.isDirectory() === true

    checks.push({
      id: 'repository.exists',
      passed: exists,
      message: exists
        ? 'Repository path exists'
        : 'Repository path does not exist'
    })

    checks.push({
      id: 'repository.directory',
      passed: isDirectory,
      message: isDirectory
        ? 'Repository path is a directory'
        : 'Repository path is not a directory'
    })

    const readable = isDirectory ? await isReadable(resolvedPath) : false

    checks.push({
      id: 'repository.readable',
      passed: readable,
      message: readable
        ? 'Repository path is readable'
        : 'Repository path is not readable'
    })

    let gitRepository = false
    let headExists = false

    if (readable) {
      try {
        const result = await this.git.run(
          ['rev-parse', '--is-inside-work-tree'],
          resolvedPath
        )

        gitRepository = result.stdout.trim() === 'true'
      } catch {
        gitRepository = false
      }

      if (gitRepository) {
        try {
          await this.git.run(
            ['rev-parse', '--verify', 'HEAD'],
            resolvedPath
          )

          headExists = true
        } catch {
          headExists = false
        }
      }
    }

    checks.push({
      id: 'repository.git',
      passed: gitRepository,
      message: gitRepository
        ? 'Target belongs to a Git work tree'
        : 'Target does not belong to a Git work tree'
    })

    checks.push({
      id: 'repository.head',
      passed: headExists,
      message: headExists
        ? 'Git repository has a valid HEAD commit'
        : 'Git repository does not have a valid HEAD commit'
    })

    return {
      timestamp: this.now().toISOString(),
      repositoryPath: resolvedPath,
      passed: checks.every((check) => check.passed),
      checks
    }
  }
}

async function isReadable(targetPath: string): Promise<boolean> {
  try {
    await access(targetPath)
    return true
  } catch {
    return false
  }
}

import type {
  SaveStepCheckpointInput,
  StepCheckpoint,
  StepCheckpointStore
} from '~/core/execution'

import { randomUUID } from 'node:crypto'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'

const validIdentifierPattern = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

export class FileStepCheckpointStore implements StepCheckpointStore {
  private readonly runsRoot: string

  constructor(runsRoot: string) {
    this.runsRoot = path.resolve(runsRoot)
  }

  async load<T>(
    runId: string,
    executionId: string
  ): Promise<StepCheckpoint<T> | null> {
    assertValidIdentifier(runId)
    assertValidIdentifier(executionId)

    const filePath = path.join(
      this.runsRoot,
      runId,
      'checkpoints',
      `${executionId}.json`
    )

    const content = await readFile(filePath, 'utf8').catch(
      (error: unknown) => {
        if (
          typeof error === 'object' &&
          error !== null &&
          'code' in error &&
          error.code === 'ENOENT'
        ) {
          return null
        }

        throw error
      }
    )

    if (content === null) {
      return null
    }

    return JSON.parse(content) as StepCheckpoint<T>
  }

  async save<T>(
    input: SaveStepCheckpointInput<T>
  ): Promise<StepCheckpoint<T>> {
    assertValidIdentifier(input.runId)
    assertValidIdentifier(input.executionId)

    const checkpoint: StepCheckpoint<T> = {
      schemaVersion: 1,
      runId: input.runId,
      step: input.step,
      executionId: input.executionId,
      inputHash: input.inputHash,
      outputHash: input.outputHash,
      attempt: input.attempt,
      workspaceRevision: input.workspaceRevision,
      createdAt: new Date().toISOString(),
      output: input.output
    }

    const directory = path.join(this.runsRoot, input.runId, 'checkpoints')

    await mkdir(directory, {
      recursive: true
    })

    const filePath = path.join(directory, `${input.executionId}.json`)

    const temporaryPath = `${filePath}.${randomUUID()}.tmp`

    await writeFile(
      temporaryPath,
      `${JSON.stringify(checkpoint, null, 2)}\n`,
      'utf8'
    )

    await rename(temporaryPath, filePath)

    return checkpoint
  }

  private async findCheckpoint(
    executionId: string
  ): Promise<string | null> {
    const runsDirectory = await import('node:fs/promises').then(
      ({ readdir }) =>
        readdir(this.runsRoot, {
          withFileTypes: true
        }).catch(() => [])
    )

    for (const entry of runsDirectory) {
      if (!entry.isDirectory()) {
        continue
      }

      const filePath = path.join(
        this.runsRoot,
        entry.name,
        'checkpoints',
        `${executionId}.json`
      )

      const exists = await import('node:fs/promises').then(({ stat }) =>
        stat(filePath)
          .then((result) => result.isFile())
          .catch(() => false)
      )

      if (exists) {
        return filePath
      }
    }

    return null
  }
}

function assertValidIdentifier(value: string): void {
  if (!validIdentifierPattern.test(value)) {
    throw new Error(`Invalid execution identifier: ${value}`)
  }
}

import { execFile } from 'node:child_process'
import { WorkspaceError, WorkspaceErrorCode } from '~/core/workspace'

export interface GitCommandResult {
  readonly stdout: string
  readonly stderr: string
}

export interface GitCommandRunnerOptions {
  readonly timeoutMs?: number
  readonly maxBufferBytes?: number
}

export class GitCommandRunner {
  private readonly timeoutMs: number
  private readonly maxBufferBytes: number

  constructor(options: GitCommandRunnerOptions = {}) {
    this.timeoutMs = options.timeoutMs ?? 30_000

    this.maxBufferBytes = options.maxBufferBytes ?? 20 * 1024 * 1024
  }

  run(args: readonly string[], cwd: string): Promise<GitCommandResult> {
    return new Promise((resolve, reject) => {
      execFile(
        'git',
        [...args],
        {
          cwd,
          encoding: 'utf8',
          timeout: this.timeoutMs,
          maxBuffer: this.maxBufferBytes,
          env: {
            ...process.env,
            GIT_TERMINAL_PROMPT: '0'
          }
        },
        (error, stdout, stderr) => {
          if (error !== null) {
            reject(
              new WorkspaceError(
                formatGitError(args, stderr),
                WorkspaceErrorCode.git_command_failed,
                {
                  cause: error
                }
              )
            )

            return
          }

          resolve({
            stdout,
            stderr
          })
        }
      )
    })
  }
}

function formatGitError(args: readonly string[], stderr: string): string {
  const details = stderr.trim()

  return details.length > 0
    ? `Git command failed: ${details}`
    : `Git command failed: git ${args.join(' ')}`
}

import type {
  ImplementationArtifactStore,
  SaveImplementationArtifactsInput,
  StoredImplementationArtifacts
} from '~/core/implementation'

import { randomUUID } from 'node:crypto'
import { mkdir, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'
import {
  ImplementerError,
  ImplementerErrorCode
} from '~/core/implementation'

const validIdentifierPattern = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

export class FileImplementationArtifactStore implements ImplementationArtifactStore {
  private readonly runsRoot: string

  constructor(
    runsRoot: string,
    private readonly now: () => Date = () => new Date()
  ) {
    this.runsRoot = path.resolve(runsRoot)
  }

  async save(
    input: SaveImplementationArtifactsInput
  ): Promise<StoredImplementationArtifacts> {
    assertValidIdentifier(input.runId, 'run')

    assertValidIdentifier(input.commandResult.executionId, 'execution')

    if (input.commandResult.runId !== input.runId) {
      throw new ImplementerError(
        'Implementation command result belongs to another run',
        ImplementerErrorCode.test_execution_failed
      )
    }

    if (
      input.commandResult.workspaceRevision !== input.workspaceRevision
    ) {
      throw new ImplementerError(
        'Implementation command result belongs to a stale workspace',
        ImplementerErrorCode.stale_workspace
      )
    }

    const suffix = input.commandResult.executionId

    const patchFileName = `implementation-${suffix}.diff`

    const resultFileName = `implementation-${suffix}.json`

    const patchRelativePath = path.posix.join('patches', patchFileName)

    const resultRelativePath = path.posix.join('agents', resultFileName)

    const patchDirectory = path.join(this.runsRoot, input.runId, 'patches')

    const agentDirectory = path.join(this.runsRoot, input.runId, 'agents')

    await Promise.all([
      mkdir(patchDirectory, {
        recursive: true
      }),

      mkdir(agentDirectory, {
        recursive: true
      })
    ])

    const patchArtifact = {
      id: `implementation-patch-${suffix}`,
      type: 'implementation.patch',
      relativePath: patchRelativePath
    } as const

    const implementationArtifact = {
      id: `implementation-result-${suffix}`,
      type: 'implementation.result',
      relativePath: resultRelativePath
    } as const

    await this.writeAtomic(
      path.join(patchDirectory, patchFileName),
      ensureTrailingNewline(input.plan.patch)
    )

    await this.writeJsonAtomic(path.join(agentDirectory, resultFileName), {
      schemaVersion: 1,

      createdAt: this.now().toISOString(),

      runId: input.runId,

      sourceWorkspaceRevision: input.sourceWorkspaceRevision,

      workspaceRevision: input.workspaceRevision,

      summary: input.plan.summary,

      changedFiles: input.plan.changedFiles,

      risks: input.plan.risks,

      reproduction: {
        testFiles: input.reproduction.testFiles,

        expectedFailureMarker: input.reproduction.expectedFailureMarker,

        failingExecutionId: input.reproduction.commandResult.executionId
      },

      patchArtifact,

      commandArtifact: input.commandResult.artifact,

      commandResult: {
        executionId: input.commandResult.executionId,

        operation: input.commandResult.operation,

        exitCode: input.commandResult.exitCode,

        signal: input.commandResult.signal,

        timedOut: input.commandResult.timedOut,

        succeeded: input.commandResult.succeeded,

        durationMs: input.commandResult.durationMs
      }
    })

    return {
      implementation: implementationArtifact,

      patch: patchArtifact,

      command: input.commandResult.artifact
    }
  }

  private async writeJsonAtomic(
    filePath: string,
    value: unknown
  ): Promise<void> {
    await this.writeAtomic(filePath, `${JSON.stringify(value, null, 2)}\n`)
  }

  private async writeAtomic(
    filePath: string,
    content: string
  ): Promise<void> {
    const temporaryPath = `${filePath}.${randomUUID()}.tmp`

    await writeFile(temporaryPath, content, 'utf8')

    await rename(temporaryPath, filePath)
  }
}

function assertValidIdentifier(value: string, kind: string): void {
  if (!validIdentifierPattern.test(value)) {
    throw new ImplementerError(
      `Invalid ${kind} identifier: ${value}`,
      ImplementerErrorCode.invalid_input
    )
  }
}

function ensureTrailingNewline(value: string): string {
  return value.endsWith('\n') ? value : `${value}\n`
}

