import type { AgentRole } from '~/core/context'
import type {
  AgentPrompt,
  PromptRegistry,
  PromptVersion,
  PromptVersionSelection,
  PromptVersionSnapshot
} from '~/core/prompt'

import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { AgentRole as AgentRoleValue } from '~/core/context'
import {
  PromptRegistryError,
  PromptRegistryErrorCode,
  createPromptVersionIdentifier,
  defaultPromptVersions
} from '~/core/prompt'

const promptVersionPattern = /^v[1-9][0-9]*$/

const promptMetadataPattern =
  /^<!-- prompt-agent: ([a-z]+) -->\r?\n<!-- prompt-version: ([a-z0-9-]+) -->\r?\n/

export interface FilePromptRegistryOptions {
  readonly promptsRoot: string
  readonly activeVersions?: PromptVersionSelection
}

export class FilePromptRegistry implements PromptRegistry {
  private readonly promptsRoot: string
  private readonly activeVersions: PromptVersionSelection
  private readonly cache = new Map<string, Promise<AgentPrompt>>()

  constructor(options: FilePromptRegistryOptions) {
    this.promptsRoot = path.resolve(options.promptsRoot)

    this.activeVersions = options.activeVersions ?? defaultPromptVersions
  }

  load(
    agent: AgentRole,
    version: PromptVersion = this.activeVersions[agent]
  ): Promise<AgentPrompt> {
    assertPromptVersion(version, agent)

    const cacheKey = `${agent}:${version}`
    const cachedPrompt = this.cache.get(cacheKey)

    if (cachedPrompt !== undefined) {
      return cachedPrompt
    }

    const loadingPrompt = this.readPrompt(agent, version).catch(
      (error: unknown) => {
        this.cache.delete(cacheKey)
        throw error
      }
    )

    this.cache.set(cacheKey, loadingPrompt)

    return loadingPrompt
  }

  loadAll(): Promise<readonly AgentPrompt[]> {
    return Promise.all(
      Object.values(AgentRoleValue).map((agent) => this.load(agent))
    )
  }

  async getVersionSnapshot(): Promise<PromptVersionSnapshot> {
    const [investigator, reproducer, implementer, reviewer] =
      await Promise.all([
        this.load(AgentRoleValue.investigator),
        this.load(AgentRoleValue.reproducer),
        this.load(AgentRoleValue.implementer),
        this.load(AgentRoleValue.reviewer)
      ] as const)

    return Object.freeze({
      [AgentRoleValue.investigator]: investigator.id,
      [AgentRoleValue.reproducer]: reproducer.id,
      [AgentRoleValue.implementer]: implementer.id,
      [AgentRoleValue.reviewer]: reviewer.id
    })
  }

  private async readPrompt(
    agent: AgentRole,
    version: PromptVersion
  ): Promise<AgentPrompt> {
    const sourcePath = path.posix.join(agent, `${version}.md`)

    const absolutePath = path.join(
      this.promptsRoot,
      agent,
      `${version}.md`
    )

    let source: string

    try {
      source = await readFile(absolutePath, 'utf8')
    } catch (error) {
      if (isFileNotFoundError(error)) {
        throw new PromptRegistryError(
          `Prompt ${agent}:${version} was not found`,
          PromptRegistryErrorCode.not_found,
          {
            agent,
            version,
            cause: error
          }
        )
      }

      throw new PromptRegistryError(
        `Failed to read prompt ${agent}:${version}`,
        PromptRegistryErrorCode.read_failed,
        {
          agent,
          version,
          cause: error
        }
      )
    }

    return parsePrompt(source, sourcePath, agent, version)
  }
}

function parsePrompt(
  source: string,
  sourcePath: string,
  expectedAgent: AgentRole,
  expectedVersion: PromptVersion
): AgentPrompt {
  const metadata = promptMetadataPattern.exec(source)

  if (metadata === null) {
    throw new PromptRegistryError(
      `Prompt ${sourcePath} does not contain valid metadata`,
      PromptRegistryErrorCode.invalid_metadata,
      {
        agent: expectedAgent,
        version: expectedVersion
      }
    )
  }

  const metadataAgent = metadata[1]
  const metadataVersion = metadata[2]

  const expectedIdentifier = createPromptVersionIdentifier(
    expectedAgent,
    expectedVersion
  )

  if (
    metadataAgent !== expectedAgent ||
    metadataVersion !== expectedIdentifier
  ) {
    throw new PromptRegistryError(
      `Prompt metadata does not match ${sourcePath}`,
      PromptRegistryErrorCode.invalid_metadata,
      {
        agent: expectedAgent,
        version: expectedVersion
      }
    )
  }

  const content = source.slice(metadata[0].length).trim()

  if (content.length === 0) {
    throw new PromptRegistryError(
      `Prompt ${sourcePath} is empty`,
      PromptRegistryErrorCode.invalid_metadata,
      {
        agent: expectedAgent,
        version: expectedVersion
      }
    )
  }

  return Object.freeze({
    id: expectedIdentifier,
    agent: expectedAgent,
    version: expectedVersion,
    content,
    sourcePath
  })
}

function assertPromptVersion(
  version: string,
  agent: AgentRole
): asserts version is PromptVersion {
  if (!promptVersionPattern.test(version)) {
    throw new PromptRegistryError(
      `Invalid prompt version: ${version}`,
      PromptRegistryErrorCode.invalid_version,
      {
        agent,
        version
      }
    )
  }
}

function isFileNotFoundError(error: unknown): boolean {
  return (
    error instanceof Error && 'code' in error && error.code === 'ENOENT'
  )
}

import type {
  ReproductionArtifactStore,
  SaveReproductionArtifactsInput,
  StoredReproductionArtifacts
} from '~/core/reproduction'

import { randomUUID } from 'node:crypto'
import { mkdir, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { ArtifactType } from '~/core/context'
import { ReproducerError, ReproducerErrorCode } from '~/core/reproduction'

const validIdentifierPattern = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

export class FileReproductionArtifactStore implements ReproductionArtifactStore {
  private readonly runsRoot: string

  constructor(
    runsRoot: string,
    private readonly now: () => Date = () => new Date()
  ) {
    this.runsRoot = path.resolve(runsRoot)
  }

  async save(
    input: SaveReproductionArtifactsInput
  ): Promise<StoredReproductionArtifacts> {
    assertValidIdentifier(input.runId, 'run')
    assertValidIdentifier(input.commandResult.executionId, 'execution')

    if (input.commandResult.runId !== input.runId) {
      throw new ReproducerError(
        'Command result belongs to another run',
        ReproducerErrorCode.test_execution_failed
      )
    }

    if (
      input.commandResult.workspaceRevision !== input.workspaceRevision
    ) {
      throw new ReproducerError(
        'Command result belongs to a stale workspace',
        ReproducerErrorCode.stale_workspace
      )
    }

    const artifactSuffix = input.commandResult.executionId

    const patchFileName = `reproduction-${artifactSuffix}.diff`

    const resultFileName = `reproduction-${artifactSuffix}.json`

    const patchRelativePath = path.posix.join('patches', patchFileName)

    const resultRelativePath = path.posix.join('agents', resultFileName)

    const patchDirectory = path.join(this.runsRoot, input.runId, 'patches')

    const agentDirectory = path.join(this.runsRoot, input.runId, 'agents')

    await Promise.all([
      mkdir(patchDirectory, {
        recursive: true
      }),
      mkdir(agentDirectory, {
        recursive: true
      })
    ])

    const patchArtifact = {
      id: `reproduction-patch-${artifactSuffix}`,
      type: 'reproduction.patch',
      relativePath: patchRelativePath
    } as const

    const reproductionArtifact = {
      id: `reproduction-test-${artifactSuffix}`,
      type: ArtifactType.reproduction_test,
      relativePath: resultRelativePath,
      workspaceRevision: input.workspaceRevision
    } as const

    await this.writeAtomic(
      path.join(patchDirectory, patchFileName),
      ensureTrailingNewline(input.plan.patch)
    )

    await this.writeJsonAtomic(path.join(agentDirectory, resultFileName), {
      schemaVersion: 1,
      createdAt: this.now().toISOString(),
      runId: input.runId,
      sourceWorkspaceRevision: input.sourceWorkspaceRevision,
      workspaceRevision: input.workspaceRevision,
      summary: input.plan.summary,
      testFiles: input.plan.testFiles,
      expectedFailureMarker: input.plan.expectedFailureMarker,
      patchArtifact,
      commandArtifact: input.commandResult.artifact,
      commandResult: {
        executionId: input.commandResult.executionId,
        operation: input.commandResult.operation,
        exitCode: input.commandResult.exitCode,
        signal: input.commandResult.signal,
        timedOut: input.commandResult.timedOut,
        succeeded: input.commandResult.succeeded,
        durationMs: input.commandResult.durationMs
      }
    })

    return {
      reproduction: reproductionArtifact,
      patch: patchArtifact,
      command: input.commandResult.artifact
    }
  }

  private async writeJsonAtomic(
    filePath: string,
    value: unknown
  ): Promise<void> {
    await this.writeAtomic(filePath, `${JSON.stringify(value, null, 2)}\n`)
  }

  private async writeAtomic(
    filePath: string,
    content: string
  ): Promise<void> {
    const temporaryPath = `${filePath}.${randomUUID()}.tmp`

    await writeFile(temporaryPath, content, 'utf8')

    await rename(temporaryPath, filePath)
  }
}

function assertValidIdentifier(value: string, kind: string): void {
  if (!validIdentifierPattern.test(value)) {
    throw new ReproducerError(
      `Invalid ${kind} identifier: ${value}`,
      ReproducerErrorCode.invalid_input
    )
  }
}

function ensureTrailingNewline(value: string): string {
  return value.endsWith('\n') ? value : `${value}\n`
}

import type {
  ReviewArtifactStore,
  SaveReviewArtifactInput,
  StoredReviewArtifact
} from '~/core/review'

import { createHash, randomUUID } from 'node:crypto'
import { mkdir, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { ReviewerError, ReviewerErrorCode } from '~/core/review'

const validIdentifierPattern = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

export class FileReviewArtifactStore implements ReviewArtifactStore {
  private readonly runsRoot: string

  constructor(
    runsRoot: string,
    private readonly now: () => Date = () => new Date()
  ) {
    this.runsRoot = path.resolve(runsRoot)
  }

  async save(
    input: SaveReviewArtifactInput
  ): Promise<StoredReviewArtifact> {
    assertValidIdentifier(input.runId, 'run')

    if (
      input.decision.workspaceRevision !==
      input.validationReport.workspaceRevision
    ) {
      throw new ReviewerError(
        'Review and validation artifacts use different workspace revisions',
        ReviewerErrorCode.stale_workspace
      )
    }

    const reviewId = randomUUID()

    const fileName = `review-${reviewId}.json`

    const relativePath = path.posix.join('agents', fileName)

    const directory = path.join(this.runsRoot, input.runId, 'agents')

    await mkdir(directory, {
      recursive: true
    })

    const artifact: StoredReviewArtifact = {
      id: `review-${reviewId}`,
      type: 'review.result',
      relativePath
    }

    await this.writeJsonAtomic(path.join(directory, fileName), {
      schemaVersion: 1,

      createdAt: this.now().toISOString(),

      runId: input.runId,

      workspaceRevision: input.decision.workspaceRevision,

      promptVersion: input.promptVersion,

      finalDiffSha256: createSha256(input.finalDiff),

      validation: {
        passed: input.validationReport.passed,

        generatedAt: input.validationReport.generatedAt,

        checks: input.validationReport.checks,

        changedFiles: input.validationReport.changedFiles,

        forbiddenFiles: input.validationReport.forbiddenFiles
      },

      recommendation: input.decision.recommendation,

      summary: input.decision.summary,

      findings: input.decision.findings,

      risks: input.decision.risks,

      publicApiChanges: input.decision.publicApiChanges
    })

    return artifact
  }

  private async writeJsonAtomic(
    filePath: string,
    value: unknown
  ): Promise<void> {
    const temporaryPath = `${filePath}.${randomUUID()}.tmp`

    await writeFile(
      temporaryPath,
      `${JSON.stringify(value, null, 2)}\n`,
      'utf8'
    )

    await rename(temporaryPath, filePath)
  }
}

function createSha256(value: string): string {
  return createHash('sha256').update(value).digest('hex')
}

function assertValidIdentifier(value: string, kind: string): void {
  if (!validIdentifierPattern.test(value)) {
    throw new ReviewerError(
      `Invalid ${kind} identifier: ${value}`,
      ReviewerErrorCode.invalid_input
    )
  }
}

import type {
  CreateRunStoreInput,
  RunState,
  RunStore,
  RunValidationReport
} from '~/core/run'

import { randomUUID } from 'node:crypto'
import { mkdir, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'

const validRunIdPattern = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

const runDirectories = [
  'workspace',
  'commands',
  'agents',
  'patches',
  'checkpoints',
  'final'
]

export class FileRunStore implements RunStore {
  private readonly runsRoot: string

  constructor(runsRoot: string) {
    this.runsRoot = path.resolve(runsRoot)
  }

  getRunDirectory(runId: string): string {
    assertValidRunId(runId)

    return path.join(this.runsRoot, runId)
  }

  async create(input: CreateRunStoreInput): Promise<void> {
    const runDirectory = this.getRunDirectory(input.state.runId)

    await mkdir(this.runsRoot, {
      recursive: true
    })

    await mkdir(runDirectory, {
      recursive: false
    })

    await Promise.all(
      runDirectories.map((directory) =>
        mkdir(path.join(runDirectory, directory))
      )
    )

    await writeFile(path.join(runDirectory, 'events.jsonl'), '', {
      encoding: 'utf8',
      flag: 'wx'
    })

    await this.writeJsonAtomic(
      path.join(runDirectory, 'state.json'),
      input.state
    )
  }

  saveState(state: RunState): Promise<void> {
    return this.writeJsonAtomic(
      path.join(this.getRunDirectory(state.runId), 'state.json'),
      state
    )
  }

  saveValidation(
    runId: string,
    report: RunValidationReport
  ): Promise<void> {
    return this.writeJsonAtomic(
      path.join(this.getRunDirectory(runId), 'validation.json'),
      report
    )
  }

  private async writeJsonAtomic(
    filePath: string,
    value: unknown
  ): Promise<void> {
    const temporaryPath = `${filePath}.${randomUUID()}.tmp`

    await writeFile(
      temporaryPath,
      `${JSON.stringify(value, null, 2)}\n`,
      'utf8'
    )

    await rename(temporaryPath, filePath)
  }
}

function assertValidRunId(runId: string): void {
  if (!validRunIdPattern.test(runId)) {
    throw new Error(`Invalid run identifier: ${runId}`)
  }
}

