export class JsonlTraceWriter implements TraceWriter {
  private readonly runsRoot: string
  private readonly fileName: string
  private queue: Promise<void> = Promise.resolve()

  constructor(options: JsonlTraceWriterOptions) {
    this.runsRoot = path.resolve(options.runsRoot)
    this.fileName = options.fileName ?? 'events.jsonl'
  }

  write(event: TraceEvent): Promise<void> {
    const operation = this.queue.then(() => this.append(event))

    this.queue = operation.catch(() => undefined)

    return operation
  }

  flush(): Promise<void> {
    return this.queue
  }

  private async append(event: TraceEvent): Promise<void> {
    assertValidRunId(event.runId)

    const runDirectory = path.join(this.runsRoot, event.runId)
    const traceFile = path.join(runDirectory, this.fileName)

    await mkdir(runDirectory, {
      recursive: true
    })

    const redactedEvent = redactSensitiveData(event)
    const line = `${JSON.stringify(redactedEvent)}\n`

    await appendFile(traceFile, line, 'utf8')
  }
}

function assertValidRunId(runId: string): void {
  if (!validRunIdPattern.test(runId)) {
    throw new Error(`Invalid trace run identifier: ${runId}`)
  }
}

import type {
  MechanicalValidationReport,
  StoredValidationReportArtifact,
  ValidationReportStore
} from '~/core/validation'

import { randomUUID } from 'node:crypto'
import { mkdir, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { ArtifactType } from '~/core/context'

const validRunIdPattern = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

export class FileValidationReportStore implements ValidationReportStore {
  private readonly runsRoot: string

  constructor(runsRoot: string) {
    this.runsRoot = path.resolve(runsRoot)
  }

  async save(
    report: MechanicalValidationReport
  ): Promise<StoredValidationReportArtifact> {
    if (!validRunIdPattern.test(report.runId)) {
      throw new Error(`Invalid validation run identifier: ${report.runId}`)
    }

    const directory = path.join(this.runsRoot, report.runId, 'validation')

    await mkdir(directory, {
      recursive: true
    })

    const fileName = 'final-validation.json'

    const relativePath = path.posix.join('validation', fileName)

    const filePath = path.join(directory, fileName)

    const temporaryPath = `${filePath}.${randomUUID()}.tmp`

    await writeFile(
      temporaryPath,
      `${JSON.stringify(report, null, 2)}\n`,
      'utf8'
    )

    await rename(temporaryPath, filePath)

    return {
      id: 'final-validation-report',
      type: ArtifactType.validation_report,
      workspaceRevision: report.workspaceRevision,
      relativePath
    }
  }
}

import type {
  ApplyPatchResult,
  CodeSearchMatch,
  ReadRepositoryFileResult,
  RepositoryFile,
  RepositoryTools,
  RepositoryToolsFactory,
  SearchCodeInput,
  WorkspaceSnapshot
} from '~/core/workspace'

import { mkdtemp, readFile, rm, stat, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { WorkspaceError, WorkspaceErrorCode } from '~/core/workspace'
import { GitCommandRunner } from '~/infra/git'
import { WorkspacePathPolicy } from '~/infra/workspace/workspace-path-policy'
import { calculateWorkspaceRevision } from '~/infra/workspace/workspace-revision'

export interface GitRepositoryToolsOptions {
  readonly maximumFileSizeBytes?: number
  readonly maximumPatchSizeBytes?: number
  readonly maximumSearchResults?: number
}

export class GitRepositoryToolsFactory implements RepositoryToolsFactory {
  constructor(
    private readonly options: GitRepositoryToolsOptions = {},
    private readonly git = new GitCommandRunner()
  ) {}

  create(workspace: WorkspaceSnapshot): RepositoryTools {
    return new GitRepositoryTools(workspace, this.git, this.options)
  }
}

export class GitRepositoryTools implements RepositoryTools {
  private readonly pathPolicy: WorkspacePathPolicy

  private readonly maximumFileSizeBytes: number

  private readonly maximumPatchSizeBytes: number

  private readonly maximumSearchResults: number

  constructor(
    private readonly workspace: WorkspaceSnapshot,
    private readonly git = new GitCommandRunner(),
    options: GitRepositoryToolsOptions = {}
  ) {
    this.pathPolicy = new WorkspacePathPolicy(workspace.workspacePath)

    this.maximumFileSizeBytes = options.maximumFileSizeBytes ?? 1024 * 1024

    this.maximumPatchSizeBytes =
      options.maximumPatchSizeBytes ?? 2 * 1024 * 1024

    this.maximumSearchResults = options.maximumSearchResults ?? 200
  }

  async listFiles(): Promise<readonly RepositoryFile[]> {
    const repositoryPaths = await this.getRepositoryFilePaths()

    const files: RepositoryFile[] = []

    for (const repositoryPath of repositoryPaths) {
      const relativePath = this.toTargetRelativePath(repositoryPath)

      if (
        relativePath === null ||
        !this.pathPolicy.isAllowed(relativePath)
      ) {
        continue
      }

      const resolved = await this.pathPolicy
        .resolveExistingFile(relativePath)
        .catch(() => null)

      if (resolved === null) {
        continue
      }

      const fileStat = await stat(resolved.absolutePath)

      files.push({
        path: relativePath,
        sizeBytes: fileStat.size
      })
    }

    return files.sort((left, right) => left.path.localeCompare(right.path))
  }

  async readFile(relativePath: string): Promise<ReadRepositoryFileResult> {
    const resolved =
      await this.pathPolicy.resolveExistingFile(relativePath)

    const fileStat = await stat(resolved.absolutePath)

    if (fileStat.size > this.maximumFileSizeBytes) {
      throw new WorkspaceError(
        `File exceeds size limit: ${relativePath}`,
        WorkspaceErrorCode.file_too_large,
        {
          path: relativePath
        }
      )
    }

    const content = await readFile(resolved.absolutePath)

    if (content.includes(0)) {
      throw new WorkspaceError(
        `Binary files are not allowed: ${relativePath}`,
        WorkspaceErrorCode.binary_file,
        {
          path: relativePath
        }
      )
    }

    return {
      path: resolved.relativePath,
      sizeBytes: fileStat.size,
      content: content.toString('utf8')
    }
  }

  async searchCode(
    input: SearchCodeInput
  ): Promise<readonly CodeSearchMatch[]> {
    if (input.query.length === 0) {
      throw new WorkspaceError(
        'Search query must not be empty',
        WorkspaceErrorCode.invalid_path
      )
    }

    const maximumResults = Math.min(
      input.maxResults ?? this.maximumSearchResults,
      this.maximumSearchResults
    )

    const query = input.caseSensitive
      ? input.query
      : input.query.toLowerCase()

    const matches: CodeSearchMatch[] = []
    const files = await this.listFiles()

    for (const file of files) {
      if (matches.length >= maximumResults) {
        break
      }

      let content: string

      try {
        content = (await this.readFile(file.path)).content
      } catch (error) {
        if (
          error instanceof WorkspaceError &&
          (error.code === WorkspaceErrorCode.binary_file ||
            error.code === WorkspaceErrorCode.file_too_large)
        ) {
          continue
        }

        throw error
      }

      const lines = content.split(/\r?\n/)

      for (let index = 0; index < lines.length; index += 1) {
        const line = lines[index] ?? ''

        const haystack = input.caseSensitive ? line : line.toLowerCase()

        const column = haystack.indexOf(query)

        if (column === -1) {
          continue
        }

        matches.push({
          path: file.path,
          line: index + 1,
          column: column + 1,
          preview: line.slice(0, 500)
        })

        if (matches.length >= maximumResults) {
          return matches
        }
      }
    }

    return matches
  }

  async applyPatch(patch: string): Promise<ApplyPatchResult> {
    const patchSize = Buffer.byteLength(patch)

    if (patchSize === 0 || patchSize > this.maximumPatchSizeBytes) {
      throw new WorkspaceError(
        'Patch is empty or exceeds the size limit',
        WorkspaceErrorCode.invalid_patch
      )
    }

    if (
      patch.includes('GIT binary patch') ||
      patch.includes('Binary files ') ||
      patch.includes('new file mode 120000')
    ) {
      throw new WorkspaceError(
        'Binary and symbolic-link patches are forbidden',
        WorkspaceErrorCode.invalid_patch
      )
    }

    const patchPaths = extractPatchPaths(patch)

    if (patchPaths.length === 0) {
      throw new WorkspaceError(
        'Patch does not contain file paths',
        WorkspaceErrorCode.invalid_patch
      )
    }

    for (const patchPath of patchPaths) {
      await this.pathPolicy.assertSafePatchPath(patchPath)
    }

    const temporaryDirectory = await mkdtemp(
      path.join(tmpdir(), 'agent-fix-patch-')
    )

    const patchFile = path.join(temporaryDirectory, 'change.patch')

    try {
      await writeFile(patchFile, patch, 'utf8')

      const directoryOption =
        this.workspace.repositoryRelativePath.length === 0
          ? []
          : [`--directory=${this.workspace.repositoryRelativePath}`]

      await this.git.run(
        [
          'apply',
          '--check',
          '--whitespace=error-all',
          ...directoryOption,
          patchFile
        ],
        this.workspace.workspaceRoot
      )

      await this.git.run(
        ['apply', '--whitespace=error-all', ...directoryOption, patchFile],
        this.workspace.workspaceRoot
      )
    } catch (error) {
      throw new WorkspaceError(
        'Patch validation or application failed',
        WorkspaceErrorCode.invalid_patch,
        {
          cause: error
        }
      )
    } finally {
      await rm(temporaryDirectory, {
        recursive: true,
        force: true
      })
    }

    return {
      changedFiles: await this.getChangedFiles(),
      workspaceRevision: await this.getWorkspaceRevision()
    }
  }

  async getDiff(): Promise<string> {
    const pathspec = this.getPathspec()

    const result = await this.git.run(
      ['diff', '--binary', '--no-ext-diff', 'HEAD', '--', pathspec],
      this.workspace.workspaceRoot
    )

    return result.stdout
  }

  async getChangedFiles(): Promise<readonly string[]> {
    const pathspec = this.getPathspec()

    const tracked = await this.git.run(
      ['diff', '--name-only', '-z', 'HEAD', '--', pathspec],
      this.workspace.workspaceRoot
    )

    const untracked = await this.git.run(
      ['ls-files', '--others', '--exclude-standard', '-z', '--', pathspec],
      this.workspace.workspaceRoot
    )

    const changedFiles = [
      ...splitNull(tracked.stdout),
      ...splitNull(untracked.stdout)
    ]
      .map((repositoryPath) => this.toTargetRelativePath(repositoryPath))
      .filter(
        (relativePath): relativePath is string =>
          relativePath !== null && this.pathPolicy.isAllowed(relativePath)
      )

    return [...new Set(changedFiles)].sort()
  }

  getWorkspaceRevision(): Promise<string> {
    return calculateWorkspaceRevision(this.workspace, this.git)
  }

  private async getRepositoryFilePaths(): Promise<string[]> {
    const result = await this.git.run(
      [
        'ls-files',
        '-co',
        '--exclude-standard',
        '-z',
        '--',
        this.getPathspec()
      ],
      this.workspace.workspaceRoot
    )

    return [...new Set(splitNull(result.stdout))]
  }

  private getPathspec(): string {
    return this.workspace.repositoryRelativePath.length === 0
      ? '.'
      : this.workspace.repositoryRelativePath
  }

  private toTargetRelativePath(repositoryPath: string): string | null {
    const normalized = repositoryPath.replaceAll('\\', '/')

    const prefix = this.workspace.repositoryRelativePath

    if (prefix.length === 0) {
      return normalized
    }

    if (normalized === prefix) {
      return null
    }

    const expectedPrefix = `${prefix}/`

    if (!normalized.startsWith(expectedPrefix)) {
      return null
    }

    return normalized.slice(expectedPrefix.length)
  }
}

function extractPatchPaths(patch: string): string[] {
  const paths: string[] = []

  for (const line of patch.split('\n')) {
    if (!line.startsWith('--- ') && !line.startsWith('+++ ')) {
      continue
    }

    const rawPath = line.slice(4).split('\t')[0]?.trim()

    if (rawPath === undefined || rawPath === '/dev/null') {
      continue
    }

    if (rawPath.startsWith('"')) {
      throw new WorkspaceError(
        'Quoted patch paths are not supported',
        WorkspaceErrorCode.invalid_patch
      )
    }

    const relativePath =
      rawPath.startsWith('a/') || rawPath.startsWith('b/')
        ? rawPath.slice(2)
        : rawPath

    paths.push(relativePath)
  }

  return [...new Set(paths)]
}

function splitNull(value: string): string[] {
  return value.split('\0').filter((item) => item.length > 0)
}

import type {
  CreateWorkspaceInput,
  WorkspaceManager,
  WorkspaceSnapshot
} from '~/core/workspace'

import { access, mkdir, rm, stat } from 'node:fs/promises'
import path from 'node:path'
import { WorkspaceError, WorkspaceErrorCode } from '~/core/workspace'
import { GitCommandRunner } from '~/infra/git'
import { calculateWorkspaceRevision } from '~/infra/workspace/workspace-revision'

const validRunIdPattern = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

export interface GitWorkspaceManagerOptions {
  readonly runsRoot: string
  readonly git?: GitCommandRunner
}

export class GitWorkspaceManager implements WorkspaceManager {
  private readonly runsRoot: string
  private readonly git: GitCommandRunner

  constructor(options: GitWorkspaceManagerOptions) {
    this.runsRoot = path.resolve(options.runsRoot)

    this.git = options.git ?? new GitCommandRunner()
  }

  async create(input: CreateWorkspaceInput): Promise<WorkspaceSnapshot> {
    assertValidRunId(input.runId)

    const repositoryPath = path.resolve(input.repositoryPath)

    await assertAccessibleDirectory(repositoryPath)

    const repositoryRoot = await this.resolveRepositoryRoot(repositoryPath)

    const repositoryRelativePath = normalizeRepositoryRelativePath(
      repositoryRoot,
      repositoryPath
    )

    const baseCommit = (
      await this.git.run(['rev-parse', '--verify', 'HEAD'], repositoryRoot)
    ).stdout.trim()

    const runDirectory = path.join(this.runsRoot, input.runId)

    const workspaceRoot = path.join(runDirectory, 'workspace')

    await mkdir(runDirectory, {
      recursive: true
    })

    await rm(workspaceRoot, {
      recursive: true,
      force: true
    })

    await this.git.run(['worktree', 'prune'], repositoryRoot)

    try {
      await this.git.run(
        ['worktree', 'add', '--detach', workspaceRoot, baseCommit],
        repositoryRoot
      )
    } catch (error) {
      await rm(workspaceRoot, {
        recursive: true,
        force: true
      })

      throw error
    }

    const workspacePath =
      repositoryRelativePath.length === 0
        ? workspaceRoot
        : path.join(workspaceRoot, repositoryRelativePath)

    const targetStat = await stat(workspacePath).catch(() => null)

    if (targetStat === null || !targetStat.isDirectory()) {
      await this.cleanupWorktree(repositoryRoot, workspaceRoot)

      throw new WorkspaceError(
        'Target repository path does not exist in the base commit',
        WorkspaceErrorCode.invalid_repository,
        {
          path: repositoryPath
        }
      )
    }

    const partialWorkspace = {
      runId: input.runId,
      repositoryPath,
      repositoryRoot,
      repositoryRelativePath,
      workspaceRoot,
      workspacePath,
      baseCommit
    }

    const workspaceRevision = await calculateWorkspaceRevision(
      partialWorkspace,
      this.git
    )

    return {
      ...partialWorkspace,
      workspaceRevision
    }
  }

  async rollback(
    workspace: WorkspaceSnapshot
  ): Promise<WorkspaceSnapshot> {
    await this.git.run(
      ['reset', '--hard', workspace.baseCommit],
      workspace.workspaceRoot
    )

    await this.git.run(['clean', '-fd'], workspace.workspaceRoot)

    const workspaceRevision = await calculateWorkspaceRevision(
      workspace,
      this.git
    )

    return {
      ...workspace,
      workspaceRevision
    }
  }

  async cleanup(workspace: WorkspaceSnapshot): Promise<void> {
    await this.cleanupWorktree(
      workspace.repositoryRoot,
      workspace.workspaceRoot
    )
  }

  private async resolveRepositoryRoot(
    repositoryPath: string
  ): Promise<string> {
    try {
      const inside = (
        await this.git.run(
          ['rev-parse', '--is-inside-work-tree'],
          repositoryPath
        )
      ).stdout.trim()

      if (inside !== 'true') {
        throw new Error('Not inside a Git work tree')
      }

      return (
        await this.git.run(
          ['rev-parse', '--show-toplevel'],
          repositoryPath
        )
      ).stdout.trim()
    } catch (error) {
      throw new WorkspaceError(
        `Target is not an accessible Git repository: ${repositoryPath}`,
        WorkspaceErrorCode.invalid_repository,
        {
          path: repositoryPath,
          cause: error
        }
      )
    }
  }

  private async cleanupWorktree(
    repositoryRoot: string,
    workspaceRoot: string
  ): Promise<void> {
    try {
      await this.git.run(
        ['worktree', 'remove', '--force', workspaceRoot],
        repositoryRoot
      )
    } catch {
      await rm(workspaceRoot, {
        recursive: true,
        force: true
      })
    }

    await this.git.run(['worktree', 'prune'], repositoryRoot)
  }
}

async function assertAccessibleDirectory(
  targetPath: string
): Promise<void> {
  const targetStat = await stat(targetPath).catch(() => null)

  if (targetStat === null || !targetStat.isDirectory()) {
    throw new WorkspaceError(
      `Repository path is not a directory: ${targetPath}`,
      WorkspaceErrorCode.invalid_repository,
      {
        path: targetPath
      }
    )
  }

  try {
    await access(targetPath)
  } catch (error) {
    throw new WorkspaceError(
      `Repository path is not accessible: ${targetPath}`,
      WorkspaceErrorCode.invalid_repository,
      {
        path: targetPath,
        cause: error
      }
    )
  }
}

function normalizeRepositoryRelativePath(
  repositoryRoot: string,
  repositoryPath: string
): string {
  const relativePath = path.relative(repositoryRoot, repositoryPath)

  if (relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
    throw new WorkspaceError(
      'Target path is outside its Git repository',
      WorkspaceErrorCode.invalid_repository,
      {
        path: repositoryPath
      }
    )
  }

  return relativePath.replaceAll(path.sep, '/')
}

function assertValidRunId(runId: string): void {
  if (!validRunIdPattern.test(runId)) {
    throw new WorkspaceError(
      `Invalid run identifier: ${runId}`,
      WorkspaceErrorCode.invalid_path
    )
  }
}

import { execFile } from 'node:child_process'
import {
  mkdir,
  mkdtemp,
  readFile,
  rm,
  stat,
  writeFile
} from 'node:fs/promises'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { WorkspaceError, WorkspaceErrorCode } from '~/core/workspace'
import {
  GitRepositoryToolsFactory,
  GitWorkspaceManager
} from '~/infra/workspace'

describe('Git workspace and repository tools', () => {
  it('creates an isolated workspace and supports repository operations', async () => {
    const temporaryRoot = await mkdtemp(
      path.join(tmpdir(), 'agent-fix-workspace-')
    )

    try {
      const repositoryRoot = path.join(temporaryRoot, 'repository')

      const targetPath = path.join(repositoryRoot, 'fixture')

      const runsRoot = path.join(temporaryRoot, 'runs')

      await createRepository(repositoryRoot, targetPath)

      await mkdir(path.join(runsRoot, 'run-001', 'workspace'), {
        recursive: true
      })

      const manager = new GitWorkspaceManager({
        runsRoot
      })

      const workspace = await manager.create({
        runId: 'run-001',
        repositoryPath: targetPath
      })

      expect(workspace.repositoryRoot).toBe(repositoryRoot)

      expect(workspace.repositoryRelativePath).toBe('fixture')

      expect(workspace.baseCommit).toMatch(/^[a-f0-9]{40}$/)

      expect(workspace.workspaceRevision).toMatch(/^sha256:/)

      const tools = new GitRepositoryToolsFactory({
        maximumFileSizeBytes: 100,
        maximumPatchSizeBytes: 10_000
      }).create(workspace)

      const files = await tools.listFiles()

      expect(files.map((file) => file.path)).toContain('src/payment.ts')

      const source = await tools.readFile('src/payment.ts')

      expect(source.content).toContain('return 1')

      const matches = await tools.searchCode({
        query: 'createPayment'
      })

      expect(matches).toMatchObject([
        {
          path: 'src/payment.ts',
          line: 1
        }
      ])

      const initialRevision = await tools.getWorkspaceRevision()

      const patch = [
        'diff --git a/src/payment.ts b/src/payment.ts',
        '--- a/src/payment.ts',
        '+++ b/src/payment.ts',
        '@@ -1,3 +1,3 @@',
        ' export function createPayment(): number {',
        '-  return 1',
        '+  return 2',
        ' }',
        ''
      ].join('\n')

      const result = await tools.applyPatch(patch)

      expect(result.changedFiles).toEqual(['src/payment.ts'])

      expect(result.workspaceRevision).not.toBe(initialRevision)

      expect(await tools.getDiff()).toContain('+  return 2')

      const rolledBack = await manager.rollback(workspace)

      expect(
        await readFile(
          path.join(rolledBack.workspacePath, 'src/payment.ts'),
          'utf8'
        )
      ).toContain('return 1')

      expect(await tools.getChangedFiles()).toEqual([])

      await manager.cleanup(rolledBack)

      await expect(stat(rolledBack.workspaceRoot)).rejects.toThrow()
    } finally {
      await rm(temporaryRoot, {
        recursive: true,
        force: true
      })
    }
  })

  it('rejects traversal, secrets, binary files and oversized files', async () => {
    const temporaryRoot = await mkdtemp(
      path.join(tmpdir(), 'agent-fix-policy-')
    )

    try {
      const repositoryRoot = path.join(temporaryRoot, 'repository')

      const runsRoot = path.join(temporaryRoot, 'runs')

      await mkdir(repositoryRoot, {
        recursive: true
      })

      await runGit(['init'], repositoryRoot)

      await writeFile(
        path.join(repositoryRoot, 'safe.ts'),
        'export const safe = true\n'
      )

      await writeFile(
        path.join(repositoryRoot, '.env'),
        'OPENAI_API_KEY=secret\n'
      )

      await writeFile(
        path.join(repositoryRoot, 'binary.bin'),
        Buffer.from([0, 1, 2, 3])
      )

      await writeFile(
        path.join(repositoryRoot, 'large.txt'),
        'x'.repeat(200)
      )

      await runGit(['add', '-f', '.'], repositoryRoot)

      await commitRepository(repositoryRoot)

      await mkdir(path.join(runsRoot, 'run-002'), {
        recursive: true
      })

      const manager = new GitWorkspaceManager({
        runsRoot
      })

      const workspace = await manager.create({
        runId: 'run-002',
        repositoryPath: repositoryRoot
      })

      const tools = new GitRepositoryToolsFactory({
        maximumFileSizeBytes: 100
      }).create(workspace)

      await expect(tools.readFile('../outside.ts')).rejects.toMatchObject({
        code: WorkspaceErrorCode.invalid_path
      })

      await expect(tools.readFile('.env')).rejects.toMatchObject({
        code: WorkspaceErrorCode.forbidden_path
      })

      await expect(tools.readFile('binary.bin')).rejects.toMatchObject({
        code: WorkspaceErrorCode.binary_file
      })

      await expect(tools.readFile('large.txt')).rejects.toMatchObject({
        code: WorkspaceErrorCode.file_too_large
      })

      await expect(
        tools.applyPatch(
          [
            'diff --git a/../outside.ts b/../outside.ts',
            '--- a/../outside.ts',
            '+++ b/../outside.ts',
            '@@ -0,0 +1 @@',
            '+unsafe',
            ''
          ].join('\n')
        )
      ).rejects.toBeInstanceOf(WorkspaceError)

      await manager.cleanup(workspace)
    } finally {
      await rm(temporaryRoot, {
        recursive: true,
        force: true
      })
    }
  })
})

async function createRepository(
  repositoryRoot: string,
  targetPath: string
): Promise<void> {
  await mkdir(path.join(targetPath, 'src'), {
    recursive: true
  })

  await runGit(['init'], repositoryRoot)

  await writeFile(
    path.join(targetPath, 'src/payment.ts'),
    [
      'export function createPayment(): number {',
      '  return 1',
      '}',
      ''
    ].join('\n')
  )

  await runGit(['add', '.'], repositoryRoot)

  await commitRepository(repositoryRoot)
}

async function commitRepository(repositoryRoot: string): Promise<void> {
  await runGit(
    [
      '-c',
      'user.name=AgentFix Test',
      '-c',
      'user.email=agent-fix@example.test',
      'commit',
      '-m',
      'initial'
    ],
    repositoryRoot
  )
}

function runGit(args: readonly string[], cwd: string): Promise<void> {
  return new Promise((resolve, reject) => {
    execFile(
      'git',
      [...args],
      {
        cwd
      },
      (error) => {
        if (error !== null) {
          // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors
          reject(error)
          return
        }

        resolve()
      }
    )
  })
}

import { lstat, realpath } from 'node:fs/promises'
import path from 'node:path'
import { WorkspaceError, WorkspaceErrorCode } from '~/core/workspace'

const forbiddenDirectoryNames = new Set([
  '.git',
  '.runs',
  '.runs-test',
  'node_modules',
  'coverage'
])

const forbiddenFileExtensions = new Set(['.pem', '.key', '.p12', '.pfx'])

export interface ResolvedWorkspaceFile {
  readonly relativePath: string
  readonly absolutePath: string
}

export class WorkspacePathPolicy {
  private readonly workspaceRoot: string

  constructor(workspaceRoot: string) {
    this.workspaceRoot = path.resolve(workspaceRoot)
  }

  resolvePath(relativePath: string): ResolvedWorkspaceFile {
    const normalized = normalizeRelativePath(relativePath)

    this.assertAllowed(normalized)

    const absolutePath = path.resolve(this.workspaceRoot, normalized)

    if (!isInsideDirectory(this.workspaceRoot, absolutePath)) {
      throw new WorkspaceError(
        `Path escapes workspace: ${relativePath}`,
        WorkspaceErrorCode.invalid_path,
        {
          path: relativePath
        }
      )
    }

    return {
      relativePath: normalized,
      absolutePath
    }
  }

  async resolveExistingFile(
    relativePath: string
  ): Promise<ResolvedWorkspaceFile> {
    const resolved = this.resolvePath(relativePath)

    await this.assertNoSymlinkSegments(resolved.relativePath)

    const fileStat = await lstat(resolved.absolutePath).catch(() => null)

    if (fileStat === null) {
      throw new WorkspaceError(
        `File does not exist: ${relativePath}`,
        WorkspaceErrorCode.file_not_found,
        {
          path: relativePath
        }
      )
    }

    if (fileStat.isSymbolicLink()) {
      throw new WorkspaceError(
        `Symbolic links are not allowed: ${relativePath}`,
        WorkspaceErrorCode.symlink_not_allowed,
        {
          path: relativePath
        }
      )
    }

    if (!fileStat.isFile()) {
      throw new WorkspaceError(
        `Path is not a regular file: ${relativePath}`,
        WorkspaceErrorCode.invalid_path,
        {
          path: relativePath
        }
      )
    }

    const actualPath = await realpath(resolved.absolutePath)

    if (!isInsideDirectory(this.workspaceRoot, actualPath)) {
      throw new WorkspaceError(
        `Resolved path escapes workspace: ${relativePath}`,
        WorkspaceErrorCode.invalid_path,
        {
          path: relativePath
        }
      )
    }

    return resolved
  }

  async assertSafePatchPath(relativePath: string): Promise<string> {
    const resolved = this.resolvePath(relativePath)

    await this.assertNoSymlinkSegments(path.dirname(resolved.relativePath))

    return resolved.relativePath
  }

  isAllowed(relativePath: string): boolean {
    try {
      this.resolvePath(relativePath)
      return true
    } catch {
      return false
    }
  }

  private assertAllowed(relativePath: string): void {
    const segments = relativePath
      .split('/')
      .map((segment) => segment.toLowerCase())

    if (segments.some((segment) => forbiddenDirectoryNames.has(segment))) {
      throw new WorkspaceError(
        `Forbidden workspace path: ${relativePath}`,
        WorkspaceErrorCode.forbidden_path,
        {
          path: relativePath
        }
      )
    }

    const baseName = segments.at(-1) ?? ''

    if (
      baseName === '.env' ||
      (baseName.startsWith('.env.') && baseName !== '.env.example')
    ) {
      throw new WorkspaceError(
        `Environment files are forbidden: ${relativePath}`,
        WorkspaceErrorCode.forbidden_path,
        {
          path: relativePath
        }
      )
    }

    const extension = path.extname(baseName)

    if (forbiddenFileExtensions.has(extension)) {
      throw new WorkspaceError(
        `Secret-bearing file is forbidden: ${relativePath}`,
        WorkspaceErrorCode.forbidden_path,
        {
          path: relativePath
        }
      )
    }
  }

  private async assertNoSymlinkSegments(
    relativePath: string
  ): Promise<void> {
    if (relativePath === '.' || relativePath.length === 0) {
      return
    }

    const segments = relativePath.split('/')
    let currentPath = this.workspaceRoot

    for (const segment of segments) {
      currentPath = path.join(currentPath, segment)

      const currentStat = await lstat(currentPath).catch(() => null)

      if (currentStat === null) {
        return
      }

      if (currentStat.isSymbolicLink()) {
        throw new WorkspaceError(
          `Symbolic link path segment is not allowed: ${relativePath}`,
          WorkspaceErrorCode.symlink_not_allowed,
          {
            path: relativePath
          }
        )
      }
    }
  }
}

function normalizeRelativePath(value: string): string {
  if (value.includes('\0') || path.isAbsolute(value)) {
    throw new WorkspaceError(
      `Invalid workspace path: ${value}`,
      WorkspaceErrorCode.invalid_path,
      {
        path: value
      }
    )
  }

  const normalized = path.posix.normalize(value.replaceAll('\\', '/'))

  if (
    normalized === '.' ||
    normalized === '..' ||
    normalized.startsWith('../')
  ) {
    throw new WorkspaceError(
      `Invalid workspace path: ${value}`,
      WorkspaceErrorCode.invalid_path,
      {
        path: value
      }
    )
  }

  return normalized
}

function isInsideDirectory(root: string, target: string): boolean {
  const relative = path.relative(root, target)

  return (
    relative.length > 0 &&
    !relative.startsWith('..') &&
    !path.isAbsolute(relative)
  )
}

import type { WorkspaceSnapshot } from '~/core/workspace'
import type { GitCommandRunner } from '~/infra/git'

import { createHash } from 'node:crypto'
import { lstat, readFile } from 'node:fs/promises'
import path from 'node:path'

export async function calculateWorkspaceRevision(
  workspace: Omit<WorkspaceSnapshot, 'workspaceRevision'>,
  git: GitCommandRunner
): Promise<string> {
  const pathspec = getPathspec(workspace)

  const diff = await git.run(
    ['diff', '--binary', '--no-ext-diff', 'HEAD', '--', pathspec],
    workspace.workspaceRoot
  )

  const untracked = await git.run(
    ['ls-files', '--others', '--exclude-standard', '-z', '--', pathspec],
    workspace.workspaceRoot
  )

  const hash = createHash('sha256')

  hash.update(workspace.baseCommit)
  hash.update('\0')
  hash.update(diff.stdout)
  hash.update('\0')

  const untrackedPaths = splitNull(untracked.stdout).sort()

  for (const repositoryPath of untrackedPaths) {
    const absolutePath = path.join(workspace.workspaceRoot, repositoryPath)

    const fileStat = await lstat(absolutePath).catch(() => null)

    if (
      fileStat === null ||
      !fileStat.isFile() ||
      fileStat.isSymbolicLink()
    ) {
      continue
    }

    hash.update(repositoryPath)
    hash.update('\0')
    hash.update(await readFile(absolutePath))
    hash.update('\0')
  }

  return `sha256:${hash.digest('hex')}`
}

function getPathspec(
  workspace: Pick<WorkspaceSnapshot, 'repositoryRelativePath'>
): string {
  return workspace.repositoryRelativePath === ''
    ? '.'
    : workspace.repositoryRelativePath
}

function splitNull(value: string): string[] {
  return value.split('\0').filter((item) => item.length > 0)
}

import { CompositionRoot } from '~/composition-root'

const root = new CompositionRoot()

const bootstrapLogger = root.logger.child({
  step: 'bootstrap'
})

let shutdownPromise: Promise<void> | undefined

async function shutdown(signal: NodeJS.Signals): Promise<void> {
  if (shutdownPromise !== undefined) {
    return shutdownPromise
  }

  removeSignalHandlers()

  shutdownPromise = (async () => {
    const shutdownLogger = root.logger.child({
      step: 'shutdown'
    })

    shutdownLogger.info(`Received ${signal}`)

    try {
      await root.app.stop()
      shutdownLogger.info('Application stopped')
    } catch (error) {
      shutdownLogger.error('Failed to stop application', {
        error
      })

      process.exitCode = 1
    } finally {
      await flushObservability()
    }
  })()

  return shutdownPromise
}

function handleSigint(): void {
  void shutdown('SIGINT')
}

function handleSigterm(): void {
  void shutdown('SIGTERM')
}

function removeSignalHandlers(): void {
  process.off('SIGINT', handleSigint)
  process.off('SIGTERM', handleSigterm)
}

async function flushObservability(): Promise<void> {
  try {
    await root.traceRecorder.flush()
  } catch (error) {
    root.logger.error('Failed to flush trace events', {
      error
    })

    process.exitCode = 1
  }

  root.logger.flush()
}

async function bootstrap(): Promise<void> {
  process.once('SIGINT', handleSigint)
  process.once('SIGTERM', handleSigterm)

  try {
    await root.app.start()

    bootstrapLogger.info('Application started')

    process.exitCode = await root.app.execute(process.argv.slice(2))
  } catch (error) {
    bootstrapLogger.error('Application execution failed', {
      error
    })

    process.exitCode = 1
  } finally {
    removeSignalHandlers()

    if (shutdownPromise !== undefined) {
      await shutdownPromise
      // eslint-disable-next-line no-unsafe-finally
      return
    }

    try {
      await root.app.stop()
      bootstrapLogger.info('Application stopped')
    } catch (error) {
      bootstrapLogger.error('Failed to stop application', {
        error
      })

      process.exitCode = 1
    }

    await flushObservability()
  }
}

await bootstrap()

import { describe, expect, it } from 'vitest'
import { CompositionRoot } from '~/composition-root'

describe('application bootstrap', () => {
  it('starts with all dependencies from the composition root', async () => {
    const { app } = new CompositionRoot()

    await expect(app.start()).resolves.toBeUndefined()

    await expect(app.execute(['--help'])).resolves.toBe(0)

    await expect(app.stop()).resolves.toBeUndefined()
  })
})

